insert into content(key,data,updated_at) values('sec:a2-r3-p7',$mkd${"id": "a2-r3-p7", "area": "RC", "group": "A급 과제", "series": 2, "round": 3, "level": "중급", "part": 7, "title": "A급 과제 3회 · PART 7 (기출독해 2문항 5·6회)", "notes": [], "items": [], "sets": [{"range": "147-148", "passage": "MEMO\nTo: All Mirifita Staff\nFrom: Kohei Stephens\nDate: 11 May\nSubject: Purchase Orders\nSeveral international shipments were sent out with invoices that lacked complete information. The error originated in our purchasing software, and our IT department is currently working to fix it. In the meantime, please double-check all orders until further notice. If you become aware of a discrepancy, see Toby Johnson for further assistance. We hope to have the root issue solved by the beginning of next month.", "tr": "회람\n수신: Mirifita 전 직원 / 발신: Kohei Stephens / 날짜: 5월 11일 / 제목: 구매 주문서\n여러 건의 국제 배송이 정보가 완전하지 않은 송장과 함께 발송되었습니다. 이 오류는 저희 구매 소프트웨어에서 비롯되었으며 IT 부서가 현재 수정 작업을 하고 있습니다. 그동안 추가 공지가 있을 때까지 모든 주문을 두 번 확인해 주십시오. 불일치를 발견하면 Toby Johnson에게 도움을 요청하십시오. 근본적인 문제는 다음 달 초까지 해결되기를 바랍니다.", "questions": [{"no": 147, "q": "What is the purpose of the memo?", "options": ["To alert staff to a problem", "To explain an updated form", "To describe a shipping method", "To announce a purchase"], "answer": 0, "explain": "정답 (A) To alert staff to a problem\n지문 개요: 송장 정보 누락 오류가 구매 소프트웨어에서 비롯되었음을 알리고, 수정될 때까지 주문을 재확인하라고 직원들에게 요청하는 회람이다.\n정답 근거: 송장 정보 누락이라는 오류를 알리고 주문을 재확인하라고 당부하고 있으므로 문제를 알리는 것이 목적이다.\n오답 분석: (B): 양식이 바뀌었다는 내용이 아니다. / (C): 배송 방법을 설명하지 않는다. / (D): 구매 발표가 아니라 구매 주문 오류 안내다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "memo": ["명사", "회람"]}}, {"no": 148, "q": "When will the IT department complete its task?", "options": ["In May", "In June", "In July", "In August"], "answer": 1, "explain": "정답 (B) In June\n정답 근거: 회람 날짜가 5월 11일이고 근본 문제를 다음 달 초까지 해결하기를 바란다고 했으므로 6월이다.\n오답 분석: (A): 5월은 회람이 작성된 달이다. / (C): 7월은 지문에서 제시된 시점이 아니다. / (D): 8월도 근거가 없다.", "g": {"when": ["접속사", "~할 때"], "will": ["조동사", "~할 것이다"], "the": ["관사", "그"], "it": ["대명사", "그것"], "department": ["명사", "부서"], "complete": ["동사", "완료하다"], "its": ["대명사", "그것의"], "task": ["명사", "과업, 일"]}}], "vocab": "shipment 명 배송(품) / invoice 명 송장, 청구서 / lack 동 ~이 없다, 부족하다 / originate in 구 ~에서 비롯되다 / in the meantime 구 그동안에 / until further notice 구 추후 공지가 있을 때까지 / discrepancy 명 불일치, 차이 / root issue 명 근본 원인 / alert 동 알리다, 경고하다 || Paraphrase: invoices that lacked complete information The error → alert staff to a problem 11 May 메모 + solved by the beginning of next month → in June", "g": {"memo": ["명사", "회람"], "to": ["전치사", "수신 / to부정사"], "all": ["한정사", "모든"], "mirifita": ["고유명사", "Mirifita(회사명)"], "staff": ["명사", "직원"], "from": ["전치사", "발신"], "kohei": ["고유명사", "Kohei(인명)"], "stephens": ["고유명사", "Stephens(인명)"], "date": ["명사", "날짜"], "11": ["숫자", "11"], "may": ["조동사", "~일 수 있다"], "subject": ["명사", "제목"], "purchase": ["명사", "구매"], "orders": ["명사", "주문", "order"], "several": ["한정사", "몇몇의"], "international": ["형용사", "국제의"], "shipments": ["명사", "배송(품)", "shipment"], "were": ["동사", "~이었다", "be"], "sent": ["과거분사", "보내진", "send"], "out": ["부사", "밖으로(send out 발송하다)"], "with": ["전치사", "~이 함께 있는"], "invoices": ["명사", "송장", "invoice"], "that": ["관계사", "~하는"], "lacked": ["동사", "~이 없었다", "lack"], "complete": ["동사", "완료하다"], "information": ["명사", "정보"], "the": ["관사", "그"], "error": ["명사", "오류"], "originated": ["동사", "비롯되었다", "originate"], "in": ["전치사", "~에(서)"], "our": ["대명사", "우리의"], "purchasing": ["명사", "구매"], "software": ["명사", "소프트웨어"], "and": ["접속사", "그리고"], "it": ["대명사", "그것"], "department": ["명사", "부서"], "is": ["동사", "~이다", "be"], "currently": ["부사", "현재"], "working": ["현재분사", "일하고 있는", "work"], "fix": ["동사", "고치다"], "meantime": ["명사", "그동안(in the meantime)"], "please": ["부사", "~해 주십시오"], "double-check": ["동사", "재확인하다"], "until": ["전치사", "~까지"], "further": ["형용사", "추가의"], "notice": ["명사", "예고, 통지"], "if": ["접속사", "만약 ~라면"], "you": ["대명사", "당신(들)"], "become": ["동사", "~하게 되다"], "aware": ["형용사", "알고 있는"], "of": ["전치사", "~의"], "a": ["관사", "하나의"], "discrepancy": ["명사", "불일치"], "see": ["동사", "찾아가다"], "toby": ["고유명사", "Toby(인명)"], "johnson": ["고유명사", "Johnson(인명)"], "for": ["전치사", "~을 위해"], "assistance": ["명사", "도움"], "we": ["대명사", "우리"], "hope": ["동사", "바라다"], "have": ["동사", "(have+목적어+pp) ~되게 하다"], "root": ["형용사", "근본적인"], "issue": ["명사", "문제"], "solved": ["과거분사", "해결된", "solve"], "by": ["전치사", "~까지"], "beginning": ["명사", "시작, 초"], "next": ["형용사", "다음의"], "month": ["명사", "달"]}}, {"range": "149-150", "passage": "Bina Rao [5:41 P.M.] Hi, Jamal. Are you still at the office?\nJamal Kerr [5:42 P.M.] Hi! Yes, I am. Everything OK?\nBina Rao [5:43 P.M.] I left early today to go talk with a client, but I left my office unlocked. I have some confidential paperwork on my desk there, but I don't have time to take the train back to work.\nJamal Kerr [5:44 P.M.] I can take care of that for you. No problem.\nBina Rao [5:45 P.M.] Thank you so much! I'm so glad you're still there.\nJamal Kerr [5:46 P.M.] No worries at all, Bina. Is there anything else I can do for you?\nBina Rao [5:47 P.M.] No, that's fine. See you tomorrow morning.", "tr": "Bina Rao [오후 5:41] 안녕하세요, Jamal. 아직 사무실에 계세요?\nJamal Kerr [오후 5:42] 안녕하세요! 네, 있어요. 무슨 일 있나요?\nBina Rao [오후 5:43] 오늘 고객과 이야기하러 일찍 나왔는데 제 사무실을 잠그지 않고 나왔어요. 책상 위에 기밀 서류가 있는데 다시 회사로 돌아갈 시간이 없어요.\nJamal Kerr [오후 5:44] 제가 처리해 드릴게요. 문제없어요.\nBina Rao [오후 5:45] 정말 감사해요! 아직 계셔서 다행이에요.\nJamal Kerr [오후 5:46] 전혀 문제없어요, Bina. 더 해 드릴 일이 있나요?\nBina Rao [오후 5:47] 아니요, 괜찮아요. 내일 아침에 봬요.", "questions": [{"no": 149, "q": "What is Ms. Rao's concern?", "options": ["She arrived too late to meet a client.", "She missed her train to the office.", "She forgot to lock her office door.", "She left a key at home."], "answer": 2, "explain": "정답 (C) She forgot to lock her office door.\n지문 개요: 일찍 퇴근한 직원이 사무실 문을 잠그지 못한 것을 걱정하며 남아 있는 동료에게 처리를 부탁하는 문자 대화다.\n정답 근거: 사무실을 잠그지 않고 나왔고 책상에 기밀 서류가 있다고 했으므로 문을 잠그지 못한 것이 걱정거리다.\n오답 분석: (A): 고객과의 만남에 늦었다는 언급이 없다. / (B): 기차를 놓친 것이 아니라 돌아갈 시간이 없다고 한다. / (D): 열쇠를 집에 두고 온 것이 아니다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "rao's": ["고유명사", "Rao의"], "concern": ["명사", "걱정거리"]}}, {"no": 150, "q": "At 5:47 P.M., what does Ms. Rao most likely mean when she writes, “No, that's fine”?", "options": ["She does not need additional help.", "A colleague will send a document to her.", "A door repair has been completed.", "She will not attend an appointment."], "answer": 0, "explain": "정답 (A) She does not need additional help.\n정답 근거: 더 도울 일이 있느냐는 물음에 대한 답이므로 추가 도움은 필요 없다는 뜻이다.\n오답 분석: (B): 서류를 보내 달라고 하지 않았다. / (C): 문 수리에 관한 내용이 없다. / (D): 약속에 불참한다는 뜻이 아니다.", "g": {"at": ["전치사", "~에"], "5:47": ["숫자", "5:47"], "p.m": ["명사", "오후"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문·부정 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "rao": ["고유명사", "Rao(인명)"], "most": ["부사", "가장"], "likely": ["부사", "아마도(most likely)"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "no": ["한정사", "어떤 ~도 없는"], "that's": ["대명사", "그것은 ~이다(that is)"], "fine": ["형용사", "괜찮은"]}}], "vocab": "unlocked 형 잠기지 않은 / confidential 형 기밀의 / paperwork 명 서류 / take care of 구 ~을 처리하다 / concern 명 걱정거리 / additional 형 추가의 || Paraphrase: I left my office unlocked → she forgot to lock her office door Is there anything else? → No, that's fine → she does not need additional help", "g": {"bina": ["고유명사", "Bina(인명)"], "rao": ["고유명사", "Rao(인명)"], "5:41": ["숫자", "5:41"], "p.m": ["명사", "오후"], "hi": ["감탄사", "안녕하세요"], "jamal": ["고유명사", "Jamal(인명)"], "are": ["동사", "~이다", "be"], "you": ["대명사", "당신(들)"], "still": ["부사", "아직"], "at": ["전치사", "~에(서)"], "the": ["관사", "그"], "office": ["명사", "사무실"], "kerr": ["고유명사", "Kerr(인명)"], "5:42": ["숫자", "5:42"], "yes": ["감탄사", "네"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "everything": ["대명사", "모든 것"], "ok": ["형용사", "괜찮은"], "5:43": ["숫자", "5:43"], "left": ["동사", "떠났다, 두고 나왔다", "leave"], "early": ["부사", "일찍"], "today": ["부사", "오늘"], "to": ["to부정사", "~하러 / ~로"], "go": ["동사", "가다"], "talk": ["동사", "이야기하다"], "with": ["전치사", "~와 함께"], "a": ["관사", "하나의"], "client": ["명사", "고객"], "but": ["접속사", "그러나"], "my": ["대명사", "나의"], "unlocked": ["형용사", "잠기지 않은"], "have": ["동사", "가지고 있다"], "some": ["한정사", "일부"], "confidential": ["형용사", "기밀의"], "paperwork": ["명사", "서류"], "on": ["전치사", "~에"], "desk": ["명사", "책상"], "there": ["부사", "그곳에"], "don't": ["조동사", "~하지 않다", "do"], "time": ["명사", "기간, 시간"], "take": ["동사", "(기차를) 타다 / (take care of) 처리하다"], "train": ["명사", "열차"], "back": ["부사", "다시, 돌아"], "work": ["명사", "직장"], "5:44": ["숫자", "5:44"], "can": ["조동사", "~할 수 있다"], "care": ["명사", "(take care of) 처리"], "of": ["전치사", "~의"], "that": ["접속사", "~라는 것"], "for": ["전치사", "~을 위해"], "no": ["감탄사", "아니요 / ~ 없는"], "problem": ["명사", "문제"], "5:45": ["숫자", "5:45"], "thank": ["동사", "감사하다"], "so": ["부사", "정말, 매우"], "much": ["부사", "많이"], "i'm": ["대명사", "나는 ~이다(I am)"], "glad": ["형용사", "기쁜"], "you're": ["대명사", "당신은 ~이다(you are)"], "5:46": ["숫자", "5:46"], "worries": ["명사", "걱정", "worry"], "all": ["한정사", "모든"], "is": ["동사", "~이다", "be"], "anything": ["대명사", "무엇이든"], "else": ["부사", "그 밖에"], "do": ["동사", "하다"], "5:47": ["숫자", "5:47"], "that's": ["대명사", "그것은 ~이다(that is)"], "fine": ["형용사", "괜찮은"], "see": ["동사", "보다, 만나다"], "tomorrow": ["부사", "내일"], "morning": ["명사", "아침"]}}, {"range": "151-152", "passage": "Sonima Sports Apparel\nSonima Sports Apparel (SSA) seeks a full-time Information Technology Specialist to perform both technical and administrative support in its London office. The position requires experience in customer service and staff training as well as in-depth knowledge of information management and computer systems. Minimum qualifications include a four-year degree in information technology and at least two years of related work experience. For a more detailed job description and information on how to apply, go to www.sssa.co.uk/careers. We plan to fill the position by 10 February.", "tr": "Sonima Sports Apparel\nSonima Sports Apparel(SSA)은 런던 사무소에서 기술 지원과 행정 지원을 모두 수행할 정규직 정보 기술 전문가를 찾습니다. 이 직책은 정보 관리와 컴퓨터 시스템에 대한 깊이 있는 지식은 물론 고객 서비스와 직원 교육 경험을 요구합니다. 최소 자격 요건은 정보 기술 분야 4년제 학위와 최소 2년의 관련 실무 경험입니다. 더 자세한 직무 설명과 지원 방법은 www.sssa.co.uk/careers에서 확인하십시오. 2월 10일까지 이 자리를 채울 계획입니다.", "questions": [{"no": 151, "q": "What is most likely true about the position?", "options": ["It requires four years of work experience.", "It involves managing a department.", "It includes travel to different SSA offices.", "It involves training SSA staff members."], "answer": 3, "explain": "정답 (D) It involves training SSA staff members.\n지문 개요: 스포츠 의류 회사가 런던 사무소의 정규직 IT 전문가를 모집하며 담당 업무, 자격 요건, 지원 방법과 채용 예정일을 알리는 공고다.\n정답 근거: 직원 교육 경험을 요구한다고 했으므로 직원을 교육하는 업무가 포함됨을 알 수 있다.\n오답 분석: (A): 4년은 학위 기간이고 요구 경력은 최소 2년이다. / (B): 부서를 관리한다는 언급이 없다. / (C): 다른 사무소 출장에 관한 내용이 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "most": ["부사", "가장"], "likely": ["부사", "아마도(most likely)"], "true": ["형용사", "사실인"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "position": ["명사", "직책"]}}, {"no": 152, "q": "What information is included in the job posting?", "options": ["The intended salary range", "The history of the company", "The expected hiring date", "The application deadline"], "answer": 2, "explain": "정답 (C) The expected hiring date\n정답 근거: 2월 10일까지 채용을 마칠 계획이라고 밝혔으므로 예상 채용 시점이 포함되어 있다.\n오답 분석: (A): 급여 범위는 제시되지 않는다. / (B): 회사 연혁 소개가 없다. / (D): 지원 마감일이 아니라 채용 예정일이다.", "g": {"what": ["대명사", "무엇"], "information": ["명사", "정보"], "is": ["동사", "~이다", "be"], "included": ["과거분사", "포함된", "include"], "in": ["전치사", "~에(서)"], "the": ["관사", "그"], "job": ["명사", "일자리"], "posting": ["명사", "공고"]}}], "vocab": "seek 동 구하다, 찾다 / administrative 형 행정의 / as well as 구 ~뿐만 아니라 / in-depth 형 심층적인 / qualification 명 자격 (요건) / related 형 관련된 / fill the position 구 자리를 충원하다 / salary range 명 급여 범위 || Paraphrase: requires experience in ~ staff training → involves training SSA staff members We plan to fill the position by 10 February → the expected hiring date", "g": {"sonima": ["고유명사", "Sonima(회사명)"], "sports": ["명사", "스포츠", "sport"], "apparel": ["명사", "의류"], "ssa": ["고유명사", "SSA(회사 약칭)"], "seeks": ["동사", "구하다", "seek"], "a": ["관사", "하나의"], "full-time": ["형용사", "정규직의"], "information": ["명사", "정보"], "technology": ["명사", "기술"], "specialist": ["명사", "전문가"], "to": ["to부정사", "~할 / ~로"], "perform": ["동사", "수행하다"], "both": ["한정사", "둘 다(both A and B)"], "technical": ["형용사", "기술의"], "and": ["접속사", "그리고"], "administrative": ["형용사", "행정의"], "support": ["명사", "지원"], "in": ["전치사", "~에(서)"], "its": ["대명사", "그것의"], "london": ["고유명사", "런던"], "office": ["명사", "사무소"], "the": ["관사", "그"], "position": ["명사", "직책"], "requires": ["동사", "필요로 하다", "require"], "experience": ["명사", "경험"], "customer": ["명사", "고객"], "service": ["명사", "서비스"], "staff": ["명사", "직원"], "training": ["명사", "교육"], "as": ["부사", "(as well as) ~뿐만 아니라"], "well": ["부사", "(as well as) ~뿐만 아니라"], "in-depth": ["형용사", "심층적인"], "knowledge": ["명사", "지식"], "of": ["전치사", "~의"], "management": ["명사", "관리"], "computer": ["명사", "컴퓨터"], "systems": ["명사", "시스템", "system"], "minimum": ["형용사", "최소의"], "qualifications": ["명사", "자격 요건", "qualification"], "include": ["동사", "포함하다"], "four-year": ["형용사", "4년제의"], "degree": ["명사", "학위"], "at": ["전치사", "~에(서)"], "least": ["형용사", "가장 적은(at least 최소한)"], "two": ["숫자", "둘"], "years": ["명사", "해, 년", "year"], "related": ["형용사", "관련된"], "work": ["명사", "업무, 일"], "for": ["전치사", "~을 위해"], "more": ["부사", "더"], "detailed": ["형용사", "자세한"], "job": ["명사", "일자리"], "description": ["명사", "설명"], "on": ["전치사", "~에"], "how": ["부사", "어떻게"], "apply": ["동사", "지원하다"], "go": ["동사", "가다, 방문하다"], "www.sssa.co.uk/careers": ["고유명사", "웹사이트 주소"], "we": ["대명사", "우리"], "plan": ["동사", "계획하다"], "fill": ["동사", "(자리를) 채우다"], "by": ["전치사", "~까지"], "10": ["숫자", "10"], "february": ["명사", "2월"]}}, {"range": "153-154", "passage": "http://www.ticketingglobalhub.com/willcall\nTicketing Global Hub offers tickets to major entertainment events around the world. Depending on the venue, tickets purchased through Ticketing Global Hub may also be picked up at a will-call box-office window. After you have chosen your event, select will-call pickup and provide your personal details and payment method. Before you submit your order, be sure to verify the spelling of the name you enter, as it must match exactly the name on the identification document that will be requested at the will-call box-office window. Please note that tickets purchased for will-call pickup are nontransferable.", "tr": "http://www.ticketingglobalhub.com/willcall\nTicketing Global Hub는 전 세계 주요 공연 행사의 티켓을 제공합니다. 공연장에 따라 Ticketing Global Hub를 통해 구매한 티켓은 현장 수령 창구에서 받을 수도 있습니다. 행사를 고른 뒤 현장 수령을 선택하고 개인 정보와 결제 수단을 입력하십시오. 주문을 제출하기 전에 입력한 이름의 철자를 반드시 확인하십시오. 현장 수령 창구에서 요구하는 신분증의 이름과 정확히 일치해야 하기 때문입니다. 현장 수령용으로 구매한 티켓은 타인에게 양도할 수 없다는 점을 유의하십시오.", "questions": [{"no": 153, "q": "What are customers advised to do when placing an order?", "options": ["Print out a proof of purchase", "Reply to a confirmation e-mail", "Check personal details for accuracy", "Select a means of identification"], "answer": 2, "explain": "정답 (C) Check personal details for accuracy\n지문 개요: 공연 예매 사이트가 현장 수령 방식의 절차와 신분 확인 요건, 양도 불가 규정을 안내하는 페이지다.\n정답 근거: 주문 제출 전에 입력한 이름의 철자를 확인하라고 당부했으므로 개인 정보의 정확성을 확인하라는 뜻이다.\n오답 분석: (A): 구매 증빙을 인쇄하라는 안내가 없다. / (B): 확인 이메일에 회신하라는 요구가 없다. / (D): 신분증 종류를 고르라는 안내는 없다.", "g": {"what": ["대명사", "무엇"], "are": ["동사", "~이다", "be"], "customers": ["명사", "고객들", "customer"], "advised": ["과거분사", "권고받는", "advise"], "to": ["to부정사", "~하라고"], "do": ["조동사", "(의문·부정 조동사)"], "when": ["접속사", "~할 때"], "placing": ["동명사", "(주문을) 하는 것", "place"], "an": ["관사", "하나의"], "order": ["명사", "주문"]}}, {"no": 154, "q": "What is indicated about will-call tickets?", "options": ["They are less expensive than regular tickets.", "They are not available for international events.", "They cannot be returned for a refund.", "They cannot be given to another person."], "answer": 3, "explain": "정답 (D) They cannot be given to another person.\n정답 근거: 현장 수령 티켓은 양도할 수 없다고 명시한다.\n오답 분석: (A): 가격 차이에 관한 언급이 없다. / (B): 전 세계 행사 티켓을 제공한다고 밝힌다. / (C): 환불에 관한 내용이 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["동사", "나타냈다", "indicate"], "about": ["전치사", "~에 관해"], "will-call": ["형용사", "현장 수령의"], "tickets": ["명사", "표, 티켓", "ticket"]}}], "vocab": "venue 명 (행사) 장소 / will-call 명 현장 수령 창구 / box office 명 매표소 / verify 동 확인하다 / match 동 일치하다 / identification 명 신분증 / nontransferable 형 양도 불가능한 / accuracy 명 정확성 || Paraphrase: verify the spelling of the name you enter → check personal details for accuracy nontransferable → they cannot be given to another person", "g": {"http://www.ticketingglobalhub.com/willcall": ["고유명사", "웹페이지 주소"], "ticketing": ["고유명사", "Ticketing(회사명 일부)"], "global": ["고유명사", "Global(회사명 일부)"], "hub": ["고유명사", "Hub(회사명 일부)"], "offers": ["동사", "제공하다", "offer"], "tickets": ["명사", "표, 티켓", "ticket"], "to": ["전치사", "~에 / to부정사"], "major": ["형용사", "주요한"], "entertainment": ["명사", "공연, 오락"], "events": ["명사", "행사", "event"], "around": ["전치사", "~ 곳곳의"], "the": ["관사", "그"], "world": ["명사", "세계"], "depending": ["전치사", "(depending on) ~에 따라"], "on": ["전치사", "~에"], "venue": ["명사", "(행사) 장소"], "purchased": ["과거분사", "구매된", "purchase"], "through": ["전치사", "~을 통해"], "may": ["조동사", "~일 수 있다"], "also": ["부사", "또한"], "be": ["동사", "~이다, 되다"], "picked": ["과거분사", "(pick up) 수령되는", "pick"], "up": ["부사", "(pick up) 수령하다"], "at": ["전치사", "~에(서)"], "a": ["관사", "하나의"], "will-call": ["형용사", "현장 수령의"], "box-office": ["명사", "매표소"], "window": ["명사", "창문"], "after": ["접속사", "~한 후에"], "you": ["대명사", "당신(들)"], "have": ["조동사", "(완료) ~했다"], "chosen": ["과거분사", "선택한", "choose"], "your": ["대명사", "당신의"], "event": ["명사", "행사"], "select": ["동사", "선택하다"], "pickup": ["명사", "수령"], "and": ["접속사", "그리고"], "provide": ["동사", "제공하다"], "personal": ["형용사", "개인의"], "details": ["명사", "세부 사항", "detail"], "payment": ["명사", "결제"], "method": ["명사", "수단, 방법"], "before": ["접속사", "~하기 전에"], "submit": ["동사", "제출하다"], "order": ["명사", "주문"], "sure": ["형용사", "확실한(be sure to 반드시 ~하다)"], "verify": ["동사", "확인하다"], "spelling": ["명사", "철자"], "of": ["전치사", "~의"], "name": ["명사", "이름"], "enter": ["동사", "입력하다"], "as": ["접속사", "~이기 때문에"], "it": ["대명사", "그것"], "must": ["조동사", "~해야 한다"], "match": ["동사", "일치하다"], "exactly": ["부사", "정확히"], "identification": ["명사", "신분 증명"], "document": ["명사", "문서"], "that": ["관계사", "~하는"], "will": ["조동사", "~할 것이다"], "requested": ["과거분사", "요구되는", "request"], "please": ["부사", "~해 주십시오"], "note": ["동사", "유의하다"], "for": ["전치사", "~을 위해"], "are": ["동사", "~이다", "be"], "nontransferable": ["형용사", "양도 불가능한"]}}, {"range": "147-148", "passage": "Food court vendors at Quinzon Shopping Plaza have come together to preserve the environment! Each weekday this month, from 12:00 noon to 2:00 P.M., we will be holding a dine-in event: diners receive a 25 percent discount if they eat their meal in our food court using our reusable tableware instead of taking it away in a disposable container. Let's eat together and save Earth!", "tr": "Quinzon 쇼핑 플라자의 푸드코트 업체들이 환경을 지키기 위해 뜻을 모았습니다! 이번 달 평일마다 정오부터 오후 2시까지 매장 식사 행사를 진행합니다. 손님이 일회용 용기에 포장해 가는 대신 저희 다회용 식기를 사용해 푸드코트에서 식사하면 25퍼센트 할인을 받습니다. 함께 먹고 지구를 지킵시다!", "sub": "기출독해 6회", "questions": [{"no": 147, "q": "What is the purpose of the event?", "options": ["To clean up the food court", "To help diners eat healthier meals", "To introduce a new menu", "To support the environment"], "answer": 3, "explain": "정답 (D) To support the environment\n지문 개요: 쇼핑몰 푸드코트 업체들이 환경 보호를 위해 다회용 식기로 매장에서 식사하는 손님에게 할인을 제공하는 행사를 알리는 광고다.\n정답 근거: 환경을 지키기 위해 업체들이 뜻을 모았다고 밝히고 일회용품 대신 다회용 식기를 권장하므로 환경 보호가 목적이다.\n오답 분석: (A): 푸드코트 청소 행사가 아니다. / (B): 건강한 식사를 돕는 것이 목적이 아니다. / (C): 새 메뉴 소개가 아니다.", "sub": "기출독해 6회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "event": ["명사", "행사"]}}, {"no": 148, "q": "How can customers receive a discount?", "options": ["By using disposable products", "By showing a 25-percent-off coupon", "By requesting a reusable plate and utensils", "By donating to a charity"], "answer": 2, "explain": "정답 (C) By requesting a reusable plate and utensils\n정답 근거: 다회용 식기를 사용해 매장에서 식사하면 25퍼센트 할인을 받는다고 했다.\n오답 분석: (A): 일회용품 사용은 할인 대상이 아니다. / (B): 쿠폰 제시 조건은 없다. / (D): 기부에 관한 언급이 없다.", "sub": "기출독해 6회", "g": {"how": ["부사", "어떻게"], "can": ["조동사", "~할 수 있다"], "customers": ["명사", "고객들", "customer"], "receive": ["동사", "받다"], "a": ["관사", "하나의"], "discount": ["명사", "할인"]}}], "vocab": "vendor 명 판매업체, 상인 / preserve 동 보존하다 / dine-in 형 매장 내 식사의 / reusable 형 재사용 가능한 / tableware 명 식기류 / disposable 형 일회용의 / container 명 용기 / utensil 명 (식사용) 도구 || Paraphrase: preserve the environment save Earth → support the environment using our reusable tableware → requesting a reusable plate and utensils", "g": {"food": ["명사", "음식"], "court": ["명사", "(food court) 푸드코트"], "vendors": ["명사", "판매업체", "vendor"], "at": ["전치사", "~에(서)"], "quinzon": ["고유명사", "Quinzon(지명)"], "shopping": ["명사", "쇼핑"], "plaza": ["명사", "플라자, 상가"], "have": ["조동사", "(완료) ~했다"], "come": ["과거분사", "모인(come together)", "come"], "together": ["부사", "함께"], "to": ["전치사", "~까지 / to부정사"], "preserve": ["동사", "보존하다"], "the": ["관사", "그"], "environment": ["명사", "환경"], "each": ["한정사", "각각의"], "weekday": ["명사", "평일"], "this": ["한정사", "이"], "month": ["명사", "달"], "from": ["전치사", "~로부터"], "12:00": ["숫자", "12:00"], "noon": ["명사", "정오"], "2:00": ["숫자", "2:00"], "p.m": ["명사", "오후"], "we": ["대명사", "우리"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "holding": ["현재분사", "개최하는", "hold"], "a": ["관사", "하나의"], "dine-in": ["형용사", "매장 내 식사의"], "event": ["명사", "행사"], "diners": ["명사", "식사 손님", "diner"], "receive": ["동사", "받다"], "25": ["숫자", "25"], "percent": ["명사", "퍼센트"], "discount": ["명사", "할인"], "if": ["접속사", "만약 ~라면"], "they": ["대명사", "그들"], "eat": ["동사", "먹다"], "their": ["대명사", "그들의"], "meal": ["명사", "식사"], "in": ["전치사", "~에서"], "our": ["대명사", "우리의"], "using": ["현재분사", "사용하여", "use"], "reusable": ["형용사", "재사용 가능한"], "tableware": ["명사", "식기류"], "instead": ["부사", "대신에(instead of)"], "of": ["전치사", "(instead of) ~ 대신"], "taking": ["동명사", "가져가는 것", "take"], "it": ["대명사", "그것(식사)"], "away": ["부사", "(take away) 포장해 가다"], "disposable": ["형용사", "일회용의"], "container": ["명사", "용기"], "let's": ["동사", "~하자(let us)"], "and": ["접속사", "그리고"], "save": ["동사", "구하다, 지키다"], "earth": ["고유명사", "지구"]}}, {"range": "149-150", "passage": "Tiff Creek Update\nCORDALE (April 30) — The area around Tiff Creek, long an eyesore to commuters on the West Valley train line, is in the final stage of restoration before its scheduled opening on July 1 as a nature park.\nThis week marks the two-year anniversary of approval of the project, although work did not commence until January. The area was previously home to an industrial glass factory. Cordale mayor Ed Scala announced today that workers are expected to complete the planting of native grasses by June. Workers have already removed old concrete and asphalt, cleaned out the creek, and replaced existing soil with sand.", "tr": "Tiff Creek 소식\n코데일(4월 30일) ― 오랫동안 West Valley 철도 노선 통근자들에게 흉물이었던 Tiff Creek 일대가 7월 1일 자연 공원으로 개장하기에 앞서 복원의 마지막 단계에 있다. 이번 주는 사업 승인 2주년이 되는 시점이지만 작업은 1월에야 시작되었다. 이 지역은 이전에 산업용 유리 공장이 있던 곳이다. 코데일 시장 Ed Scala는 오늘 작업자들이 6월까지 자생 풀 심기를 마칠 것으로 예상된다고 발표했다. 작업자들은 이미 낡은 콘크리트와 아스팔트를 걷어내고 하천을 정비했으며 기존 흙을 모래로 교체했다.", "sub": "기출독해 6회", "questions": [{"no": 149, "q": "When did the restoration work begin?", "options": ["In January", "In April", "In June", "In July"], "answer": 0, "explain": "정답 (A) In January\n지문 개요: 공장 부지였던 하천 주변을 자연 공원으로 복원하는 사업의 착공 시점과 지금까지의 작업, 앞으로의 일정을 전하는 기사다.\n정답 근거: 사업 승인은 2년 전이지만 실제 작업은 1월에야 시작되었다고 명시한다.\n오답 분석: (B): 4월 30일은 기사 작성일이다. / (C): 6월은 풀 심기를 마칠 예정 시점이다. / (D): 7월 1일은 공원 개장 예정일이다.", "sub": "기출독해 6회", "g": {"when": ["접속사", "~할 때"], "did": ["조동사", "(과거 의문·부정)", "do"], "the": ["관사", "그"], "restoration": ["명사", "복원"], "work": ["명사", "작품"], "begin": ["동사", "시작하다"]}}, {"no": 150, "q": "According to the article, what will happen next?", "options": ["A factory will be repaired.", "Grasses will be planted.", "A train station will be completed.", "Soil will be replaced."], "answer": 1, "explain": "정답 (B) Grasses will be planted.\n정답 근거: 콘크리트 제거, 하천 정비, 흙 교체는 이미 끝났고 자생 풀 심기를 6월까지 마칠 예정이라고 했으므로 다음 작업은 풀 심기다.\n오답 분석: (A): 공장은 예전에 있던 시설이며 수리 계획이 없다. / (C): 기차역 공사 이야기가 아니다. / (D): 흙 교체는 이미 완료된 작업이다.", "sub": "기출독해 6회", "g": {"according": ["전치사", "(according to) ~에 따르면"], "to": ["전치사", "(according to) ~에"], "the": ["관사", "그"], "article": ["명사", "기사"], "what": ["대명사", "무엇"], "will": ["조동사", "~할 것이다"], "happen": ["동사", "일어나다"], "next": ["부사", "다음에"]}}], "vocab": "eyesore 명 흉물, 보기 흉한 것 / commuter 명 통근자 / restoration 명 복원 / mark 동 (기념일 등이) 되다 / approval 명 승인 / commence 동 시작되다 / native 형 토착의, 자생의 / replace A with B 구 A를 B로 교체하다 || Paraphrase: work did not commence until January → in January complete the planting of native grasses by June → grasses will be planted", "g": {"tiff": ["고유명사", "Tiff(지명)"], "creek": ["명사", "하천, 개울"], "update": ["동사", "최신 정보를 알리다"], "cordale": ["고유명사", "코데일(지명)"], "april": ["명사", "4월"], "30": ["숫자", "30"], "the": ["관사", "그"], "area": ["명사", "지역"], "around": ["전치사", "~ 곳곳의"], "long": ["부사", "오랫동안"], "an": ["관사", "하나의"], "eyesore": ["명사", "흉물"], "to": ["전치사", "~에게"], "commuters": ["명사", "통근자", "commuter"], "on": ["전치사", "~에"], "west": ["고유명사", "West(노선명 일부)"], "valley": ["고유명사", "Valley(지명 일부)"], "train": ["명사", "열차"], "line": ["명사", "노선"], "is": ["동사", "~이다", "be"], "in": ["전치사", "~에(서)"], "final": ["형용사", "마지막의"], "stage": ["명사", "단계"], "of": ["전치사", "~의"], "restoration": ["명사", "복원"], "before": ["전치사", "~ 전에"], "its": ["대명사", "그것의"], "scheduled": ["과거분사", "예정된", "schedule"], "opening": ["명사", "개장"], "july": ["명사", "7월"], "1": ["숫자", "1"], "as": ["전치사", "~로서"], "a": ["관사", "하나의"], "nature": ["명사", "자연"], "park": ["명사", "공원"], "this": ["한정사", "이"], "week": ["명사", "주"], "marks": ["동사", "(기념일이) 되다", "mark"], "two-year": ["형용사", "2년의"], "anniversary": ["명사", "기념일"], "approval": ["명사", "승인"], "project": ["명사", "사업"], "although": ["접속사", "비록 ~지만"], "work": ["명사", "작업"], "did": ["조동사", "(과거 의문·부정)", "do"], "not": ["부사", "~ 않다"], "commence": ["동사", "시작되다"], "until": ["전치사", "(not until) ~에야"], "january": ["명사", "1월"], "was": ["동사", "~이었다", "be"], "previously": ["부사", "이전에"], "home": ["명사", "(~이) 있던 곳"], "industrial": ["형용사", "산업의"], "glass": ["명사", "유리"], "factory": ["명사", "공장"], "mayor": ["명사", "시장"], "ed": ["고유명사", "Ed(인명)"], "scala": ["고유명사", "Scala(인명)"], "announced": ["동사", "발표했다", "announce"], "today": ["부사", "오늘"], "that": ["접속사", "~라고"], "workers": ["명사", "작업자", "worker"], "are": ["동사", "~이다", "be"], "expected": ["과거분사", "예상되는", "expect"], "complete": ["동사", "마치다"], "planting": ["명사", "심기"], "native": ["형용사", "자생의"], "grasses": ["명사", "풀", "grass"], "by": ["전치사", "~까지"], "june": ["명사", "6월"], "have": ["조동사", "(완료) ~했다"], "already": ["부사", "이미"], "removed": ["과거분사", "제거한", "remove"], "old": ["형용사", "낡은"], "concrete": ["명사", "콘크리트"], "and": ["접속사", "그리고"], "asphalt": ["명사", "아스팔트"], "cleaned": ["과거분사", "(clean out) 깨끗이 치운", "clean"], "out": ["부사", "(clean out) 깨끗이"], "replaced": ["과거분사", "교체한", "replace"], "existing": ["형용사", "기존의"], "soil": ["명사", "흙"], "with": ["전치사", "~와 함께"], "sand": ["명사", "모래"]}}, {"range": "151-152", "passage": "Shekeia Jacobs [9:04 A.M.] Hello. I called into the video conference, but no one else was on the line. When the meeting date was changed, was the phone number or dial-in code also changed?\nKarl Rudd [9:05 A.M.] It's today at 10. It was previously scheduled for 9, but when we changed the date, we also moved the start time. I'm sorry that I forgot to send you the update.\nShekeia Jacobs [9:07 A.M.] It's fine. Is the dial-in information the same?\nKarl Rudd [9:08 A.M.] Yes.\nShekeia Jacobs [9:09 A.M.] Thanks. I am just glad I didn't miss it. See you on the call soon!", "tr": "Shekeia Jacobs [오전 9:04] 안녕하세요. 화상 회의에 접속했는데 아무도 없네요. 회의 날짜가 바뀔 때 전화번호나 접속 코드도 바뀌었나요?\nKarl Rudd [오전 9:05] 오늘 10시입니다. 원래 9시로 잡혀 있었는데 날짜를 바꾸면서 시작 시간도 옮겼어요. 변경 사항을 보내 드리는 걸 잊어서 죄송합니다.\nShekeia Jacobs [오전 9:07] 괜찮습니다. 접속 정보는 그대로인가요?\nKarl Rudd [오전 9:08] 네.\nShekeia Jacobs [오전 9:09] 감사합니다. 놓치지 않아서 다행이에요. 곧 회의에서 뵐게요!", "sub": "기출독해 6회", "questions": [{"no": 151, "q": "Why did Ms. Jacobs contact Mr. Rudd?", "options": ["To give him a recommendation", "To change a dial-in code", "To inquire about a meeting", "To cancel a video call"], "answer": 2, "explain": "정답 (C) To inquire about a meeting\n지문 개요: 회의 시간이 변경된 것을 몰랐던 직원이 접속 정보와 일정을 확인하는 문자 대화다.\n정답 근거: 회의에 접속했으나 아무도 없어 접속 정보와 일정이 바뀌었는지 묻고 있으므로 회의에 관해 문의하는 것이다.\n오답 분석: (A): 추천을 하는 내용이 아니다. / (B): 접속 코드를 바꾸려는 것이 아니라 바뀌었는지 묻는 것이다. / (D): 화상 통화를 취소하려는 것이 아니다.", "sub": "기출독해 6회", "g": {"why": ["부사", "왜"], "did": ["조동사", "(과거 의문·부정)", "do"], "ms": ["명사", "~씨(여성)"], "jacobs": ["고유명사", "Jacobs(인명)"], "contact": ["동사", "연락하다"], "mr": ["명사", "~씨(남성)"], "rudd": ["고유명사", "Rudd(인명)"]}}, {"no": 152, "q": "At 9:07 A.M., what does Ms. Jacobs most likely mean when she writes, “It's fine”?", "options": ["A new time is acceptable to her.", "The list of participants is final.", "She approves of the location for a meeting.", "She likes some updated phone equipment."], "answer": 0, "explain": "정답 (A) A new time is acceptable to her.\n정답 근거: 시간이 10시로 바뀌었고 알리지 못해 미안하다는 말에 대한 대답이므로 바뀐 시간이 괜찮다는 뜻이다.\n오답 분석: (B): 참석자 명단 이야기가 아니다. / (C): 회의 장소는 언급되지 않는다. / (D): 전화 장비에 관한 내용이 아니다.", "sub": "기출독해 6회", "g": {"at": ["전치사", "~에(서)"], "9:07": ["숫자", "9:07"], "a.m": ["명사", "오전"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문·부정 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "jacobs": ["고유명사", "Jacobs(인명)"], "most": ["부사", "가장"], "likely": ["부사", "아마도(most likely)"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "it's": ["대명사", "그것은 ~이다(it is)"], "fine": ["형용사", "괜찮은"]}}], "vocab": "call into 구 (전화로) 접속하다 / dial-in code 명 접속 코드 / previously 부 이전에 / update 명 최신 정보 / inquire about 구 ~에 대해 문의하다 / acceptable 형 받아들일 수 있는 || Paraphrase: was the phone number or dial-in code also changed? → inquire about a meeting 시간 변경 사과 → It's fine → a new time is acceptable to her", "g": {"shekeia": ["고유명사", "Shekeia(인명)"], "jacobs": ["고유명사", "Jacobs(인명)"], "9:04": ["숫자", "9:04"], "a.m": ["명사", "오전"], "hello": ["감탄사", "안녕하세요"], "i": ["대명사", "나"], "called": ["동사", "(call into) 전화로 접속했다", "call"], "into": ["전치사", "~ 안으로"], "the": ["관사", "그"], "video": ["명사", "비디오"], "conference": ["명사", "회의"], "but": ["접속사", "그러나"], "no": ["한정사", "아무 ~도 없는"], "one": ["대명사", "사람(no one 아무도)"], "else": ["부사", "그 밖에"], "was": ["동사", "~이었다", "be"], "on": ["전치사", "~에 (접속한)"], "line": ["명사", "(전화) 회선"], "when": ["접속사", "~할 때"], "meeting": ["명사", "회의"], "date": ["명사", "날짜"], "changed": ["과거분사", "바뀐", "change"], "phone": ["명사", "전화"], "number": ["명사", "번호"], "or": ["접속사", "또는"], "dial-in": ["형용사", "전화 접속용의"], "code": ["명사", "코드"], "also": ["부사", "또한"], "karl": ["고유명사", "Karl(인명)"], "rudd": ["고유명사", "Rudd(인명)"], "9:05": ["숫자", "9:05"], "it's": ["대명사", "그것은 ~이다(it is)"], "today": ["부사", "오늘"], "at": ["전치사", "~에"], "10": ["숫자", "10"], "it": ["대명사", "그것(회의)"], "previously": ["부사", "이전에"], "scheduled": ["과거분사", "예정된", "schedule"], "for": ["전치사", "~로"], "9": ["숫자", "9"], "we": ["대명사", "우리"], "moved": ["동사", "옮겼다", "move"], "start": ["명사", "시작"], "time": ["명사", "기간, 시간"], "i'm": ["대명사", "나는 ~이다(I am)"], "sorry": ["형용사", "미안한"], "that": ["접속사", "~라는 것"], "forgot": ["동사", "잊었다", "forget"], "to": ["to부정사", "~하는 것"], "send": ["동사", "보내다"], "you": ["대명사", "당신(들)"], "update": ["동사", "최신 정보를 알리다"], "9:07": ["숫자", "9:07"], "fine": ["형용사", "괜찮은"], "is": ["동사", "~이다", "be"], "information": ["명사", "정보"], "same": ["형용사", "같은"], "9:08": ["숫자", "9:08"], "yes": ["감탄사", "네"], "9:09": ["숫자", "9:09"], "thanks": ["명사", "고마워요"], "am": ["동사", "~이다", "be"], "just": ["부사", "막, 단지"], "glad": ["형용사", "기쁜"], "didn't": ["조동사", "~하지 않았다", "do"], "miss": ["동사", "놓치다"], "see": ["동사", "만나 보다, 찾아가다"], "call": ["명사", "통화"], "soon": ["부사", "곧"]}}, {"range": "153-154", "passage": "To: Pamela Doan\nFrom: Sara Atwater\nSubject: Jewelry sales\nDate: 5 July\nDear Ms. Doan,\nThank you for meeting with me yesterday to discuss selling my handmade earrings in your World Treasures Shop. I am thrilled that you would consider selling my designs with your other fine merchandise. I can remember saving money from my first part-time job to buy a bracelet there for my mother's birthday.\nThe consignment arrangement we discussed wherein you would receive 20 percent of the sales price is agreeable to me. I would like to begin our six-month trial period on 1 August. May I come to set up my display that morning about an hour before the shop opens?\nSincerely, Sara Atwater", "tr": "수신: Pamela Doan / 발신: Sara Atwater / 제목: 장신구 판매 / 날짜: 7월 5일\nDoan 씨께,\n어제 만나 제 수제 귀걸이를 World Treasures Shop에서 판매하는 문제를 논의해 주셔서 감사합니다. 제 디자인을 그 훌륭한 다른 상품들과 함께 판매해 주실 것을 고려해 주신다니 무척 기쁩니다. 첫 아르바이트로 모은 돈으로 어머니 생신 선물로 그곳에서 팔찌를 샀던 기억이 납니다. 판매가의 20퍼센트를 받으시는 위탁 판매 조건은 저에게 만족스럽습니다. 6개월 시범 기간을 8월 1일에 시작하고 싶습니다. 그날 아침 매장 개점 한 시간쯤 전에 진열대를 설치하러 가도 될까요?\nSara Atwater 드림", "sub": "기출독해 6회", "questions": [{"no": 153, "q": "What is indicated about Ms. Atwater?", "options": ["She has previously worked at World Treasures Shop.", "She sells products from World Treasures Shop in her store.", "She is applying for a job at World Treasures Shop.", "She is a former customer of World Treasures Shop."], "answer": 3, "explain": "정답 (D) She is a former customer of World Treasures Shop.\n지문 개요: 수공예 귀걸이 제작자가 매장 위탁 판매 조건에 동의하며 진열 준비를 위한 방문 시간을 요청하는 이메일이다.\n정답 근거: 첫 아르바이트로 모은 돈으로 그 가게에서 팔찌를 샀던 기억을 언급했으므로 예전 고객이었다.\n오답 분석: (A): 그곳에서 일한 적이 있다는 언급은 없다. / (B): 자기 매장에서 그 가게 상품을 파는 것이 아니다. / (C): 취업 지원이 아니라 위탁 판매 논의다.", "sub": "기출독해 6회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["동사", "나타냈다", "indicate"], "about": ["전치사", "~에 관해"], "ms": ["명사", "~씨(여성)"], "atwater": ["고유명사", "Atwater(인명)"]}}, {"no": 154, "q": "What is Ms. Atwater requesting?", "options": ["A time when she can go to the shop", "A 20 percent share of the profits", "An extension of her initial trial period", "A larger display area that she can use"], "answer": 0, "explain": "정답 (A) A time when she can go to the shop\n정답 근거: 8월 1일 아침 개점 한 시간 전에 진열대를 설치하러 가도 되는지 물었으므로 방문 시간을 요청하는 것이다.\n오답 분석: (B): 20퍼센트는 상대가 받는 몫이며 이미 동의했다. / (C): 시범 기간 연장을 요구하지 않았다. / (D): 진열 공간 확대 요청은 없다.", "sub": "기출독해 6회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "ms": ["명사", "~씨(여성)"], "atwater": ["고유명사", "Atwater(인명)"], "requesting": ["현재분사", "요청하는", "request"]}}], "vocab": "handmade 형 수제의 / merchandise 명 상품 / consignment 명 위탁 (판매) / arrangement 명 합의, 방식 / wherein 관계부사 그 안에서 ~하는 / agreeable 형 동의할 만한 / trial period 명 시험 기간 / set up 구 설치하다 / former 형 이전의 || Paraphrase: saving money ~ to buy a bracelet there → a former customer of World Treasures Shop May I come ~ an hour before the shop opens? → a time when she can go to the shop", "g": {"to": ["전치사", "수신, ~에게 / to부정사"], "pamela": ["고유명사", "Pamela(인명)"], "doan": ["고유명사", "Doan(인명)"], "from": ["전치사", "~로부터"], "sara": ["고유명사", "Sara(인명)"], "atwater": ["고유명사", "Atwater(인명)"], "subject": ["명사", "제목"], "jewelry": ["명사", "장신구"], "sales": ["명사", "판매", "sale"], "date": ["명사", "날짜"], "5": ["숫자", "5"], "july": ["명사", "7월"], "dear": ["형용사", "친애하는"], "ms": ["명사", "~씨(여성)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신(들)"], "for": ["전치사", "~에 대해 / ~을 위해"], "meeting": ["동명사", "만나는 것", "meet"], "with": ["전치사", "~와 함께"], "me": ["대명사", "나를"], "yesterday": ["부사", "어제"], "discuss": ["동사", "논의하다"], "selling": ["동명사", "판매하는 것", "sell"], "my": ["대명사", "나의"], "handmade": ["형용사", "수제의"], "earrings": ["명사", "귀걸이", "earring"], "in": ["전치사", "~에(서)"], "your": ["대명사", "당신의"], "world": ["명사", "세계"], "treasures": ["고유명사", "Treasures(상호 일부)"], "shop": ["명사", "가게"], "i": ["대명사", "나"], "am": ["동사", "~이다", "be"], "thrilled": ["형용사", "무척 기쁜"], "that": ["접속사", "~라는 것"], "would": ["조동사", "~할 것이다"], "consider": ["동사", "고려하다"], "designs": ["명사", "디자인 제품", "design"], "other": ["형용사", "다른"], "fine": ["형용사", "훌륭한"], "merchandise": ["명사", "상품"], "can": ["조동사", "~할 수 있다"], "remember": ["동사", "기억하다"], "saving": ["동명사", "모으는 것", "save"], "money": ["명사", "돈"], "first": ["형용사", "첫 번째의"], "part-time": ["형용사", "시간제의"], "job": ["명사", "일자리"], "buy": ["동사", "사다"], "a": ["관사", "하나의"], "bracelet": ["명사", "팔찌"], "there": ["부사", "그곳에서"], "mother's": ["명사", "어머니의", "mother"], "birthday": ["명사", "생일"], "the": ["관사", "그"], "consignment": ["명사", "위탁 판매"], "arrangement": ["명사", "합의, 방식"], "we": ["대명사", "우리"], "discussed": ["동사", "논의했다", "discuss"], "wherein": ["관계사", "그 안에서 ~하는"], "receive": ["동사", "받다"], "20": ["숫자", "20"], "percent": ["명사", "퍼센트"], "of": ["전치사", "~의"], "price": ["명사", "가격"], "is": ["동사", "~이다", "be"], "agreeable": ["형용사", "동의할 만한"], "like": ["동사", "(would like to) ~하고 싶다"], "begin": ["동사", "시작하다"], "our": ["대명사", "우리의"], "six-month": ["형용사", "6개월의"], "trial": ["명사", "시험, 시범"], "period": ["명사", "기간"], "on": ["전치사", "~에"], "1": ["숫자", "1"], "august": ["명사", "8월"], "may": ["조동사", "~일 수 있다"], "come": ["동사", "오다"], "set": ["동사", "(set up) 설치하다"], "up": ["부사", "(set up) 설치하다"], "display": ["명사", "진열대"], "morning": ["명사", "아침"], "about": ["부사", "약, 대략"], "an": ["관사", "하나의"], "hour": ["명사", "시간"], "before": ["접속사", "~하기 전에"], "opens": ["동사", "문을 열다", "open"], "sincerely": ["부사", "진심으로(맺음말)"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r4-p5',$mkd${"id": "a2-r4-p5", "area": "RC", "group": "A급 과제", "series": 2, "round": 4, "level": "중급", "part": 5, "title": "A급 과제 4회 · PART 5 (문법 7·8회)", "notes": ["114(문법 7회)·115(문법 8회): 문제지 원본에 (D) 보기가 없어 해설 오답 분석 (D) 설명에 맞춰 보충함 — 114 (D) open, 115 (D) participated"], "items": [{"no": 101, "q": "The research department at Ogus Company _____ a more fuel-efficient car.", "options": ["develop", "developer", "developed", "development"], "answer": 2, "explain": "정답 (C) developed\n해석: Ogus 사의 연구 부서는 연비가 더 좋은 자동차를 개발했다.\n정답 근거: 문장에 동사가 없고 빈칸 뒤에 목적어 a more fuel-efficient car가 있으므로 능동태 동사가 필요하다. 주어 department가 단수이므로 developed가 정답이다.\n오답 분석: (A) develop: 단수 주어와 수가 맞지 않는다. / (B) developer: 명사가 두 개 연달아 와 구조가 성립하지 않는다. / (D) development: 명사는 문장의 동사가 될 수 없다.", "translation": "Ogus 사의 연구 부서는 연비가 더 좋은 자동차를 개발했다.", "vocab": "research department 명 연구 부서 / fuel-efficient 형 연비가 좋은 / develop 동 개발하다", "g": {"the": ["관사", "그"], "research": ["명사", "연구"], "department": ["명사", "부서"], "at": ["전치사", "~에(서)"], "ogus": ["고유명사", "Ogus(회사명)"], "company": ["명사", "회사"], "a": ["관사", "하나의"], "more": ["부사", "더"], "fuel-efficient": ["형용사", "연비가 좋은"], "car": ["명사", "자동차"]}, "src": "1-"}, {"no": 103, "q": "Choosing a suitable location is the _____ factor in opening an additional service center.", "options": ["importantly", "more importantly", "most important", "as important as"], "answer": 2, "explain": "정답 (C) most important\n해석: 적합한 위치를 고르는 것은 추가 서비스 센터를 여는 데 가장 중요한 요소이다.\n정답 근거: 관사 the와 명사 factor 사이이므로 형용사 자리다. the와 함께 쓰이므로 최상급 most important가 정답이다.\n오답 분석: (A) importantly: 부사는 명사를 꾸밀 수 없다. / (B) more importantly: 부사의 비교급이라 명사를 수식하지 못한다. / (D) as important as: 비교 구문이라 the 뒤 명사 수식 자리에 들어갈 수 없다.", "translation": "적합한 위치를 고르는 것은 추가 서비스 센터를 여는 데 가장 중요한 요소이다.", "vocab": "suitable 형 적합한 / factor 명 요인 / additional 형 추가의 / most important 최상급 가장 중요한", "g": {"choosing": ["동명사", "고르는 것", "choose"], "a": ["관사", "하나의"], "suitable": ["형용사", "적합한"], "location": ["명사", "위치, 장소"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "factor": ["명사", "요인"], "in": ["전치사", "~하는 데 있어"], "opening": ["동명사", "여는 것", "open"], "an": ["관사", "하나의"], "additional": ["형용사", "추가의"], "service": ["명사", "서비스"], "center": ["명사", "센터"]}, "src": "1-"}, {"no": 105, "q": "Employees must obtain _____ from their supervisor for purchases made after May 1.", "options": ["to author", "authorize", "authoritative", "authorization"], "answer": 3, "explain": "정답 (D) authorization\n해석: 직원들은 5월 1일 이후의 구매에 대해 상사에게서 승인을 받아야 한다.\n정답 근거: 타동사 obtain 뒤에 목적어가 없으므로 빈칸은 목적어인 명사 자리다.\n오답 분석: (A) to author: to부정사는 obtain의 목적어로 쓰이지 않는다. / (B) authorize: 동사는 목적어가 될 수 없다. / (C) authoritative: 형용사가 꾸밀 명사가 없다.", "translation": "직원들은 5월 1일 이후의 구매에 대해 상사에게서 승인을 받아야 한다.", "vocab": "obtain 동 얻다, 받다 / authorization 명 승인, 허가 / supervisor 명 상사, 관리자", "g": {"employees": ["명사", "직원들", "employee"], "must": ["조동사", "~해야 한다"], "obtain": ["동사", "얻다, 받다"], "from": ["전치사", "~로부터"], "their": ["대명사", "그들의"], "supervisor": ["명사", "상사"], "for": ["전치사", "~에 대해"], "purchases": ["명사", "구매", "purchase"], "made": ["과거분사", "이루어진", "make"], "after": ["전치사", "~ 이후에"], "may": ["명사", "5월"], "1": ["숫자", "1"]}, "src": "1-"}, {"no": 106, "q": "Tracks 1 and 2 are _____ closed for maintenance at East Station.", "options": ["period", "periods", "periodic", "periodically"], "answer": 3, "explain": "정답 (D) periodically\n해석: 1번과 2번 선로는 East 역에서 정기적으로 정비를 위해 폐쇄된다.\n정답 근거: be동사와 과거분사 closed 사이이므로 동사를 꾸미는 부사 자리다.\n오답 분석: (A) period: 명사는 be동사와 분사 사이에 올 수 없다. / (B) periods: 복수 명사도 같은 이유로 불가하다. / (C) periodic: 형용사가 꾸밀 명사가 없다.", "translation": "1번과 2번 선로는 East 역에서 정기적으로 정비를 위해 폐쇄된다.", "vocab": "periodically 부 주기적으로 / maintenance 명 유지 보수 / track 명 선로", "g": {"tracks": ["명사", "선로", "track"], "1": ["숫자", "1"], "and": ["접속사", "그리고"], "2": ["숫자", "2"], "are": ["동사", "~이다", "be"], "closed": ["과거분사", "폐쇄된", "close"], "for": ["전치사", "~을 위해"], "maintenance": ["명사", "정비, 유지 보수"], "at": ["전치사", "~에(서)"], "east": ["고유명사", "East(역명 일부)"], "station": ["명사", "역"]}, "src": "1-"}, {"no": 108, "q": "At present, Wheldon-Kent Tech _____ to deliver a long-overdue firmware update to consumers.", "options": ["was worked", "is working", "has been worked", "working"], "answer": 1, "explain": "정답 (B) is working\n해석: 현재 Wheldon-Kent Tech는 오래 지연된 펌웨어 업데이트를 소비자에게 제공하려고 작업 중이다.\n정답 근거: At present가 현재 시점을 나타내므로 현재진행형이 알맞고, work는 자동사여서 수동태로 쓰이지 않는다.\n오답 분석: (A) was worked: 자동사는 수동태로 쓸 수 없고 시제도 맞지 않는다. / (C) has been worked: 자동사의 수동태라 성립하지 않는다. / (D) working: 분사는 문장의 동사가 될 수 없다.", "translation": "현재 Wheldon-Kent Tech는 오래 지연된 펌웨어 업데이트를 소비자에게 제공하려고 작업 중이다.", "vocab": "at present 구 현재 / long-overdue 형 오래 지연된 / deliver 동 제공하다, 내놓다", "g": {"at": ["전치사", "~에(서)"], "present": ["명사", "현재(at present)"], "wheldon-kent": ["고유명사", "Wheldon-Kent(회사명)"], "tech": ["고유명사", "Tech(회사명 일부)"], "to": ["to부정사", "~하려고 / ~에게"], "deliver": ["동사", "제공하다, 내놓다"], "a": ["관사", "하나의"], "long-overdue": ["형용사", "오래 지연된"], "firmware": ["명사", "펌웨어"], "update": ["명사", "업데이트"], "consumers": ["명사", "소비자", "consumer"]}, "src": "1-"}, {"no": 109, "q": "Tools by Parsen Hardware are made with a patented synthetic _____ that resists corrosion.", "options": ["substance", "substances", "substantial", "substantive"], "answer": 0, "explain": "정답 (A) substance\n해석: Parsen Hardware의 공구는 부식에 강한 특허받은 합성 물질로 만들어진다.\n정답 근거: 관사 a와 형용사 patented synthetic의 수식을 받는 단수 명사 자리이므로 substance가 정답이다.\n오답 분석: (B) substances: 관사 a가 있으므로 복수 명사는 불가하다. / (C) substantial: 형용사가 꾸밀 명사가 없다. / (D) substantive: 형용사도 같은 이유로 불가하다.", "translation": "Parsen Hardware의 공구는 부식에 강한 특허받은 합성 물질로 만들어진다.", "vocab": "patented 형 특허받은 / synthetic 형 합성의 / substance 명 물질 / resist corrosion 구 부식에 강하다", "g": {"tools": ["명사", "공구", "tool"], "by": ["전치사", "~에 의해"], "parsen": ["고유명사", "Parsen(회사명)"], "hardware": ["고유명사", "Hardware(회사명 일부)"], "are": ["동사", "~이다", "be"], "made": ["과거분사", "이루어진", "make"], "with": ["전치사", "~으로"], "a": ["관사", "하나의"], "patented": ["형용사", "특허받은"], "synthetic": ["형용사", "합성의"], "that": ["관계사", "~하는(것)"], "resists": ["동사", "~에 강하다, 견디다", "resist"], "corrosion": ["명사", "부식"]}, "src": "1-"}, {"no": 113, "q": "Mr. Hinojosa will tell the marketing team members _____ the meeting will be held.", "options": ["who", "what", "whose", "when"], "answer": 3, "explain": "정답 (D) when\n해석: Hinojosa 씨가 마케팅 팀원들에게 회의가 언제 열릴지 알려 줄 것이다.\n정답 근거: tell의 두 번째 목적어인 명사절을 이끄는 자리다. 뒤 문장 the meeting will be held가 주어와 동사를 갖춘 완전한 문장이므로 의문부사 when이 정답이다.\n오답 분석: (A) who: 뒤에 주어가 빠져 있어야 하는데 완전한 문장이다. / (B) what: 마찬가지로 뒤 문장에 빠진 성분이 있어야 한다. / (C) whose: 뒤에 명사가 이어져야 한다.", "translation": "Hinojosa 씨가 마케팅 팀원들에게 회의가 언제 열릴지 알려 줄 것이다.", "vocab": "hold a meeting 구 회의를 열다 / when 의문사 언제", "g": {"mr": ["명사", "~씨(남성)"], "hinojosa": ["고유명사", "Hinojosa(인명)"], "will": ["조동사", "~할 것이다"], "tell": ["동사", "말하다, 알려 주다"], "the": ["관사", "그"], "marketing": ["명사", "마케팅"], "team": ["명사", "팀"], "members": ["명사", "구성원, 회원", "member"], "meeting": ["명사", "회의"], "be": ["동사", "~이다, 되다"], "held": ["과거분사", "열리는", "hold"]}, "src": "1-"}, {"no": 114, "q": "CEO Charlie Gittlin's autobiography _____ discusses the financial difficulties he overcame at the start of his career.", "options": ["opened", "opens", "openly", "open"], "answer": 2, "explain": "정답 (C) openly\n해석: 최고 경영자 Charlie Gittlin의 자서전은 그가 경력 초기에 극복한 재정적 어려움을 솔직하게 다룬다.\n정답 근거: 주어와 동사 discusses 사이이고 뒤에 목적어가 이미 있으므로 동사를 꾸미는 부사 자리다.\n오답 분석: (A) opened: 동사가 두 개가 되어 불가하다. / (B) opens: 같은 이유로 동사를 또 쓸 수 없다. / (D) 나머지 선택지도 동사·형용사 형태라 부사 자리에 올 수 없다.", "translation": "최고 경영자 Charlie Gittlin의 자서전은 그가 경력 초기에 극복한 재정적 어려움을 솔직하게 다룬다.", "vocab": "autobiography 명 자서전 / openly 부 솔직하게, 공개적으로 / overcome – overcame 동 극복하다", "g": {"ceo": ["명사", "최고 경영자"], "charlie": ["고유명사", "Charlie(인명)"], "gittlin's": ["고유명사", "Gittlin의"], "autobiography": ["명사", "자서전"], "discusses": ["동사", "다루다", "discuss"], "the": ["관사", "그"], "financial": ["형용사", "재정적인"], "difficulties": ["명사", "어려움", "difficulty"], "he": ["대명사", "그"], "overcame": ["동사", "극복했다", "overcome"], "at": ["전치사", "~에(서)"], "start": ["명사", "시작"], "of": ["전치사", "~의"], "his": ["대명사", "그의"], "career": ["명사", "경력"]}, "src": "1-"}, {"no": 115, "q": "All members must sign in at the front desk before _____ the gym.", "options": ["enter", "entered", "entering", "enters"], "answer": 2, "explain": "정답 (C) entering\n해석: 모든 회원은 체육관에 들어가기 전에 안내 데스크에서 방문 기록을 해야 한다.\n정답 근거: before는 전치사로 쓰일 때 뒤에 동명사가 오고, enter는 타동사여서 뒤에 목적어 the gym이 이어지므로 entering이 정답이다. after·before·while·when·since 뒤에 -ing가 오는 대표적인 형태다.\n오답 분석: (A) enter: 동사원형은 전치사 뒤에 올 수 없다. / (B) entered: 과거형·과거분사는 이 구조에 맞지 않는다. / (D) enters: 동사가 두 개가 되어 불가하다.", "translation": "모든 회원은 체육관에 들어가기 전에 안내 데스크에서 방문 기록을 해야 한다.", "vocab": "sign in 구 입장 기록을 하다 / before -ing 구 ~하기 전에 / enter 동 들어가다", "g": {"all": ["한정사", "모든"], "members": ["명사", "구성원, 회원", "member"], "must": ["조동사", "~해야 한다"], "sign": ["동사", "(sign in) 방문 기록을 하다"], "in": ["부사", "(sign in) 방문 기록을 하다"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "front": ["형용사", "앞쪽의(front desk 안내 데스크)"], "desk": ["명사", "데스크"], "before": ["전치사", "~ 전에"], "gym": ["명사", "체육관"]}, "src": "1-"}, {"no": 120, "q": "Video games are designed to allow players to win a _____ number of times.", "options": ["reasonably", "reason", "reasoning", "reasonable"], "answer": 3, "explain": "정답 (D) reasonable\n해석: 비디오 게임은 참가자가 적당한 횟수만큼 이길 수 있도록 설계된다.\n정답 근거: 관사 a와 명사 number 사이이므로 형용사 자리다.\n오답 분석: (A) reasonably: 부사는 명사를 꾸밀 수 없다. / (B) reason: 명사가 연달아 와 뜻이 성립하지 않는다. / (C) reasoning: 분사·명사여서 number를 꾸미기에 어색하다.", "translation": "비디오 게임은 참가자가 적당한 횟수만큼 이길 수 있도록 설계된다.", "vocab": "be designed to do 구 ~하도록 설계되다 / allow A to do 구 A가 ~하게 하다 / reasonable 형 적당한, 합리적인", "g": {"video": ["명사", "비디오"], "games": ["명사", "게임", "game"], "are": ["동사", "~이다", "be"], "designed": ["과거분사", "설계된", "design"], "to": ["to부정사", "~하기 위해, ~하는"], "allow": ["동사", "허용하다, ~하게 하다"], "players": ["명사", "참가자", "player"], "win": ["동사", "이기다"], "a": ["관사", "하나의"], "number": ["명사", "수, 횟수"], "of": ["전치사", "~의"], "times": ["명사", "번, 회", "time"]}, "src": "1-"}, {"no": 122, "q": "The undergoing piping system _____ to be in accordance with all the conditions stipulated in the contract.", "options": ["will find", "had found", "was found", "finding"], "answer": 2, "explain": "정답 (C) was found\n해석: 시공 중인 배관 시스템은 계약에 명시된 모든 조건에 부합하는 것으로 확인되었다.\n정답 근거: find는 타동사인데 빈칸 뒤에 목적어(명사)가 없고 to부정사만 이어지므로 수동태가 정답이다.\n오답 분석: (A) will find: 능동태라 뒤에 목적어가 있어야 한다. / (B) had found: 능동태이므로 같은 이유로 불가하다. / (D) finding: 분사는 문장의 동사가 될 수 없다.\n정답 한눈에 보기\n101 || 103 || 105 || 107 || 109 || 111 || 113\n(C) || (A) || (C) || (D) || (B) || (A) || (B)\n115 || 119 || 121 || 123 || 125 || 127 ||\n(B) || (B) || (C) || (C) || (B) || (A) ||", "translation": "시공 중인 배관 시스템은 계약에 명시된 모든 조건에 부합하는 것으로 확인되었다.", "vocab": "be found to be 구 ~인 것으로 판명되다 / in accordance with 구 ~에 부합하는 / stipulate 동 (계약서에) 명기하다", "g": {"the": ["관사", "그"], "undergoing": ["현재분사", "(공사가) 진행 중인", "undergo"], "piping": ["명사", "배관"], "system": ["명사", "시스템"], "to": ["to부정사", "~하는 것으로(be found to be)"], "be": ["동사", "~이다, 되다"], "in": ["전치사", "(in accordance with) ~에 부합하는"], "accordance": ["명사", "일치(in accordance with ~에 부합하는)"], "with": ["전치사", "~와"], "all": ["한정사", "모든"], "conditions": ["명사", "조건", "condition"], "stipulated": ["과거분사", "명시된", "stipulate"], "contract": ["명사", "계약(서)"]}, "src": "1-"}, {"no": 101, "q": "Ms. Reynolds and _____ team will make a presentation at the meeting tomorrow.", "options": ["she", "herself", "her", "hers"], "answer": 2, "explain": "정답 (C) her\n해석: Reynolds 씨와 그녀의 팀이 내일 회의에서 발표할 것이다.\n정답 근거: 빈칸 뒤에 명사 team이 있으므로 명사 앞 소유격 자리다.\n오답 분석: (A) she: 주격은 명사를 꾸밀 수 없다. / (B) herself: 재귀대명사는 명사를 수식하지 못한다. / (D) hers: 소유대명사 뒤에는 명사가 올 수 없다.", "translation": "Reynolds 씨와 그녀의 팀이 내일 회의에서 발표할 것이다.", "sub": "문법 8회", "vocab": "make a presentation 구 발표하다 / her 소유격 그녀의", "g": {"ms": ["명사", "~씨(여성)"], "reynolds": ["고유명사", "Reynolds(인명)"], "and": ["접속사", "그리고"], "team": ["명사", "팀"], "will": ["조동사", "~할 것이다"], "make": ["동사", "하다(make a presentation 발표하다)"], "a": ["관사", "하나의"], "presentation": ["명사", "발표"], "at": ["전치사", "~에(서)"], "the": ["관사", "그"], "meeting": ["명사", "회의"], "tomorrow": ["부사", "내일"]}, "src": "2-"}, {"no": 103, "q": "Linwald Paints is introducing a new line of _____ colors that will be available just in time for spring.", "options": ["bright", "brightly", "brighten", "brightness"], "answer": 0, "explain": "정답 (A) bright\n해석: Linwald Paints는 봄에 딱 맞춰 출시될 밝은 색상의 신제품군을 선보이고 있다.\n정답 근거: 전치사 of의 목적어인 명사 colors 앞이므로 형용사 자리다.\n오답 분석: (B) brightly: 부사는 명사를 꾸밀 수 없다. / (C) brighten: 동사는 명사를 수식하지 못한다. / (D) brightness: 명사가 연달아 와 어색하다.", "translation": "Linwald Paints는 봄에 딱 맞춰 출시될 밝은 색상의 신제품군을 선보이고 있다.", "sub": "문법 8회", "vocab": "introduce 동 출시하다, 선보이다 / a line of 구 ~ 제품군 / bright 형 밝은, 선명한 / in time for 구 ~에 맞춰", "g": {"linwald": ["고유명사", "Linwald(회사명)"], "paints": ["고유명사", "Paints(회사명 일부)"], "is": ["동사", "~이다", "be"], "introducing": ["현재분사", "선보이는", "introduce"], "a": ["관사", "하나의"], "new": ["형용사", "새로운"], "line": ["명사", "제품군"], "of": ["전치사", "~의"], "colors": ["명사", "색상", "color"], "that": ["관계사", "~하는"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "available": ["형용사", "구할 수 있는"], "just": ["부사", "딱, 마침"], "in": ["전치사", "(in time for) ~에 맞춰"], "time": ["명사", "시간(in time for ~에 맞춰)"], "for": ["전치사", "~에 (맞춰)"], "spring": ["명사", "봄"]}, "src": "2-"}, {"no": 105, "q": "The opening day of Valmage Gallery's new exhibition was a huge _____.", "options": ["successful", "successfully", "success", "succeed"], "answer": 2, "explain": "정답 (C) success\n해석: Valmage 갤러리 새 전시의 개막일은 큰 성공이었다.\n정답 근거: be동사 뒤 보어 자리이고 관사 a와 형용사 huge의 수식을 받으므로 명사 success가 정답이다.\n오답 분석: (A) successful: 형용사는 관사 a 뒤에서 단독 보어가 될 수 없다. / (B) successfully: 부사는 보어가 될 수 없다. / (D) succeed: 동사는 be동사 뒤에 올 수 없다.", "translation": "Valmage 갤러리 새 전시의 개막일은 큰 성공이었다.", "sub": "문법 8회", "vocab": "exhibition 명 전시회 / success 명 성공 / huge 형 엄청난", "g": {"the": ["관사", "그"], "opening": ["명사", "개막"], "day": ["명사", "날"], "of": ["전치사", "~의"], "valmage": ["고유명사", "Valmage(갤러리명)"], "gallery's": ["명사", "갤러리의", "gallery"], "new": ["형용사", "새