insert into content(key,data,updated_at) values('sec:a2-r4-p7',$mkd${"id": "a2-r4-p7", "area": "RC", "group": "A급 과제", "series": 2, "round": 4, "level": "중급", "part": 7, "title": "A급 과제 4회 · PART 7 (기출독해 2문항 7·8회)", "notes": [], "items": [], "sets": [{"range": "147-148", "passage": "WESTOVER BUILDING · Directory\nPhi Import Services ··· Suite 100\nRivera & Pao Law ··· Suite 200\nStarcrest Insurance, Inc. ··· Suite 145\nCormac Advertising ··· Suite 255\nCallon Hill Lending ··· Suite 180\nBurchell Investment Group ··· Suite 275\nLeasing and maintenance by Kellan Holdings. 555-0198", "tr": "WESTOVER 빌딩 · 안내\nPhi Import Services ··· 100호 / Rivera & Pao Law ··· 200호\nStarcrest Insurance ··· 145호 / Cormac Advertising ··· 255호\nCallon Hill Lending ··· 180호 / Burchell Investment Group ··· 275호\n임대 및 관리: Kellan Holdings. 555-0198", "questions": [{"no": 147, "q": "Where is the sign most likely posted?", "options": ["At a hotel reception desk", "At a shopping mall", "In a law office", "In a building lobby"], "answer": 3, "explain": "정답 (D) In a building lobby\n지문 개요: 건물에 입주한 업체들의 호실 정보를 정리하고 임대·관리 담당사와 연락처를 표기한 안내판이다.\n정답 근거: 한 건물 안 여러 업체의 호실을 안내하는 표지판이므로 건물 로비에 게시되었을 가능성이 크다.\n오답 분석: (A): 호텔 프런트 안내가 아니라 입주 업체 목록이다. / (B): 쇼핑몰 매장이 아니라 사무실 호실이다. / (C): 법률 사무소는 입주 업체 중 하나일 뿐이다.", "g": {"where": ["부사", "어디에"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "sign": ["동사", "(sign in) 방문 기록을 하다"], "most": ["부사", "가장"], "likely": ["부사", "아마도(most likely)"], "posted": ["과거분사", "게시된", "post"]}}, {"no": 148, "q": "What service does Kellan Holdings probably provide?", "options": ["Employment counseling", "Property management", "Business investing", "Architectural design"], "answer": 1, "explain": "정답 (B) Property management\n정답 근거: 임대와 유지 관리를 Kellan Holdings가 맡는다고 표기했으므로 건물 관리 서비스를 제공한다.\n오답 분석: (A): 취업 상담과 무관하다. / (C): 투자 업무는 다른 입주사의 영역이다. / (D): 건축 설계 언급이 없다.", "g": {"what": ["대명사", "무엇"], "service": ["명사", "서비스"], "does": ["조동사", "(의문·부정 조동사)", "do"], "kellan": ["고유명사", "Kellan(회사명)"], "holdings": ["고유명사", "Holdings(회사명 일부)"], "probably": ["부사", "아마"], "provide": ["동사", "제공하다"]}}], "vocab": "directory 명 (입주사) 안내판 / suite 명 (사무실) 호실 / leasing 명 임대 / maintenance 명 유지 보수 / property management 명 부동산 관리 / post 동 게시하다 || Paraphrase: directory → in a building lobby Leasing and maintenance by Kellan Holdings → property management", "g": {"westover": ["고유명사", "Westover(건물명)"], "building": ["명사", "건물"], "directory": ["명사", "(입주사) 안내판"], "phi": ["고유명사", "Phi(회사명)"], "import": ["고유명사", "Import(회사명 일부)"], "services": ["고유명사", "Services(회사명 일부)"], "suite": ["명사", "(사무실) 호실"], "100": ["숫자", "100"], "rivera": ["고유명사", "Rivera(인명)"], "pao": ["고유명사", "Pao(인명)"], "law": ["고유명사", "Law(법률 사무소명 일부)"], "200": ["숫자", "200"], "starcrest": ["고유명사", "Starcrest(회사명)"], "insurance": ["고유명사", "Insurance(회사명 일부)"], "inc": ["명사", "주식회사(Inc.)"], "145": ["숫자", "145"], "cormac": ["고유명사", "Cormac(회사명)"], "advertising": ["고유명사", "Advertising(회사명 일부)"], "255": ["숫자", "255"], "callon": ["고유명사", "Callon(회사명)"], "hill": ["고유명사", "Hill(회사명 일부)"], "lending": ["고유명사", "Lending(회사명 일부)"], "180": ["숫자", "180"], "burchell": ["고유명사", "Burchell(회사명)"], "investment": ["고유명사", "Investment(회사명 일부)"], "group": ["고유명사", "Group(회사명 일부)"], "275": ["숫자", "275"], "leasing": ["명사", "임대"], "and": ["접속사", "그리고"], "maintenance": ["명사", "정비, 유지 보수"], "by": ["전치사", "~에 의한, ~ 담당"], "kellan": ["고유명사", "Kellan(회사명)"], "holdings": ["고유명사", "Holdings(회사명 일부)"], "555-0198": ["숫자", "555-0198"]}}, {"range": "149-150", "passage": "20th Annual Lilac Festival\nJoin us May 1 to May 24 at the Vernonville Lilac Festival. Fresh flowers, food, beverages, gifts, and a children's play area will be available for the whole family. Please note that we have new hours this year. We will be open from 8:00 A.M. to 7:00 P.M. daily, rain or shine.\nFor busy weekends, we recommend purchasing tickets online ahead of time to avoid the ticket booth lines. Visit our Web site at www.vvlilacfestival.org. For large groups of ten or more, call our office at 616-555-0137 to discuss reduced group-ticket pricing.", "tr": "제20회 연례 라일락 축제\n5월 1일부터 5월 24일까지 Vernonville 라일락 축제에 함께하세요. 신선한 꽃, 음식, 음료, 선물, 어린이 놀이 공간이 온 가족을 위해 준비됩니다. 올해는 운영 시간이 새로 바뀌었음을 알려 드립니다. 날씨와 관계없이 매일 오전 8시부터 오후 7시까지 운영합니다. 붐비는 주말에는 매표소 줄을 피하기 위해 온라인 사전 구매를 권합니다. www.vvlilacfestival.org를 방문하십시오. 10명 이상 단체는 616-555-0137로 사무실에 전화해 단체 할인가를 문의하십시오.", "questions": [{"no": 149, "q": "What is indicated about the festival?", "options": ["It takes place every two years.", "It is open only on weekends.", "Its location has moved.", "Its hours have changed."], "answer": 3, "explain": "정답 (D) Its hours have changed.\n지문 개요: 연례 라일락 축제의 기간과 바뀐 운영 시간, 온라인 예매 권장과 단체 할인 안내를 담은 홍보 엽서다.\n정답 근거: 올해는 운영 시간이 새로 바뀌었다고 명시한다.\n오답 분석: (A): 연례 축제라고 했으므로 격년이 아니다. / (B): 매일 운영한다고 밝힌다. / (C): 장소 이전에 관한 언급이 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "명시된", "indicate"], "about": ["전치사", "~에 관해"], "the": ["관사", "그"], "festival": ["명사", "축제"]}}, {"no": 150, "q": "What is suggested about large groups?", "options": ["They can obtain a discount.", "They can gain early admission.", "They must register at a Web site.", "They must purchase tickets in advance."], "answer": 0, "explain": "정답 (A) They can obtain a discount.\n정답 근거: 10명 이상 단체는 전화로 단체 할인가를 문의하라고 했으므로 할인을 받을 수 있다.\n오답 분석: (B): 조기 입장 혜택은 언급되지 않는다. / (C): 단체는 전화로 문의하라고 안내한다. / (D): 사전 구매는 붐비는 주말 방문객 전체에 대한 권장 사항이다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 관해"], "large": ["형용사", "많은, 큰"], "groups": ["명사", "단체", "group"]}}], "vocab": "annual 형 연례의 / beverage 명 음료 / rain or shine 구 날씨에 상관없이 / ahead of time 구 미리 / avoid 동 피하다 / reduced 형 할인된 / pricing 명 가격 (책정) / obtain 동 얻다 || Paraphrase: we have new hours this year → its hours have changed reduced group-ticket pricing → they can obtain a discount", "g": {"20th": ["숫자", "제20회"], "annual": ["형용사", "연례의"], "lilac": ["명사", "라일락"], "festival": ["명사", "축제"], "join": ["동사", "함께하다, 참여하다"], "us": ["대명사", "우리를"], "may": ["조동사", "~일 수 있다"], "1": ["숫자", "1"], "to": ["전치사", "~까지 / to부정사"], "24": ["숫자", "24"], "at": ["전치사", "~에서 / ~로"], "the": ["관사", "그"], "vernonville": ["고유명사", "Vernonville(지명)"], "fresh": ["형용사", "신선한"], "flowers": ["명사", "꽃", "flower"], "food": ["명사", "음식"], "beverages": ["명사", "음료", "beverage"], "gifts": ["명사", "선물", "gift"], "and": ["접속사", "그리고"], "a": ["관사", "하나의"], "children's": ["명사", "어린이의", "child"], "play": ["명사", "놀이"], "area": ["명사", "공간, 구역"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "available": ["형용사", "구할 수 있는"], "for": ["전치사", "~을 위한 / ~에"], "whole": ["형용사", "전체의"], "family": ["명사", "가족"], "please": ["부사", "~해 주십시오"], "note": ["동사", "유의하다"], "that": ["접속사", "~라는 것"], "we": ["대명사", "우리"], "have": ["조동사", "(완료) ~했다"], "new": ["형용사", "새로운"], "hours": ["명사", "시간", "hour"], "this": ["한정사", "이"], "year": ["명사", "해"], "open": ["형용사", "문을 연, 운영하는"], "from": ["전치사", "~부터"], "8:00": ["숫자", "8:00"], "a.m": ["명사", "오전"], "7:00": ["숫자", "7:00"], "p.m": ["명사", "오후"], "daily": ["형용사", "일간의"], "rain": ["명사", "비"], "or": ["접속사", "또는"], "shine": ["명사", "맑음(rain or shine 날씨와 관계없이)"], "busy": ["형용사", "붐비는"], "weekends": ["명사", "주말", "weekend"], "recommend": ["동사", "권하다"], "purchasing": ["동명사", "구매하는 것", "purchase"], "tickets": ["명사", "표, 티켓", "ticket"], "online": ["형용사", "온라인의"], "ahead": ["부사", "(ahead of time) 미리"], "of": ["전치사", "~의"], "time": ["명사", "시간(ahead of time 미리)"], "avoid": ["동사", "피하다"], "ticket": ["명사", "표, 티켓"], "booth": ["명사", "부스, 매표소"], "lines": ["명사", "줄", "line"], "visit": ["동사", "방문하다"], "our": ["대명사", "우리의"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "www.vvlilacfestival.org": ["고유명사", "웹사이트 주소"], "large": ["형용사", "큰(대규모의)"], "groups": ["명사", "단체", "group"], "ten": ["숫자", "열"], "more": ["형용사", "더 많은"], "call": ["동사", "전화하다"], "office": ["명사", "사무실"], "616-555-0137": ["숫자", "616-555-0137"], "discuss": ["동사", "논의하다, 문의하다"], "reduced": ["형용사", "할인된"], "group-ticket": ["형용사", "단체 표의"], "pricing": ["명사", "가격 (책정)"]}}, {"range": "151-152", "passage": "To: Research and Development Staff\nFrom: Laurel Altmann\nDate: July 10\nSubject: Dr. Decker\nDear colleagues,\nAfter fifteen years at Marabay Labs, senior research scientist Rosamond Decker is leaving to move to New Zealand, where she will be joining the engineering faculty at Wareham University. A farewell party for Dr. Decker will be held at Bistro Georgiana on July 24 at 7 P.M. We will be celebrating her accomplishments at Marabay and presenting her with a gift to wish her well as she returns to teaching, one of her passions.\nTo indicate that you plan to attend, please register at www.marabaylab4.com/events/4591 so that we know how many people to expect. If you would like to make a donation toward the gift, contact Jake Woloch at extension 256.\nKind regards, Laurel Altmann, Administrative Manager", "tr": "수신: 연구 개발 부서 직원 / 발신: Laurel Altmann / 날짜: 7월 10일 / 제목: Decker 박사\n동료 여러분께,\nMarabay Labs에서 15년을 보낸 선임 연구 과학자 Rosamond Decker가 뉴질랜드로 이주해 Wareham 대학교 공학부에 합류하기 위해 떠납니다. Decker 박사의 송별회가 7월 24일 오후 7시 Bistro Georgiana에서 열립니다. Marabay에서의 업적을 축하하고, 그녀의 열정 중 하나인 교직으로 돌아가는 것을 응원하는 선물을 전달할 예정입니다. 참석 의사를 알리시려면 www.marabaylab4.com/events/4591에서 등록해 인원을 파악할 수 있게 해 주십시오. 선물 비용을 보태고 싶으시면 내선 256번의 Jake Woloch에게 연락하십시오.\n행정 관리자 Laurel Altmann 드림", "questions": [{"no": 151, "q": "Why did Ms. Altmann send the e-mail?", "options": ["To invite employees to a celebration", "To introduce a newly hired scientist", "To announce an award recipient", "To inform employees about a staff promotion"], "answer": 0, "explain": "정답 (A) To invite employees to a celebration\n지문 개요: 선임 연구원의 이직에 따른 송별회 일정과 참석 등록, 선물 기부 방법을 안내하는 사내 이메일이다.\n정답 근거: 송별회 일정과 장소를 알리고 참석 등록을 요청하고 있으므로 직원들을 행사에 초대하는 것이 목적이다.\n오답 분석: (B): 신규 채용 과학자를 소개하는 것이 아니다. / (C): 수상자 발표가 아니다. / (D): 승진 안내가 아니라 이직에 따른 송별이다.", "g": {"why": ["부사", "왜"], "did": ["조동사", "(과거 의문·부정)", "do"], "ms": ["명사", "~씨(여성)"], "altmann": ["고유명사", "Altmann(인명)"], "send": ["동사", "보내다"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"]}}, {"no": 152, "q": "What is suggested about Dr. Decker?", "options": ["She is originally from New Zealand.", "She has made a donation to Marabay Labs.", "She is training Mr. Woloch.", "She has accepted a teaching position."], "answer": 3, "explain": "정답 (D) She has accepted a teaching position.\n정답 근거: 대학 공학부에 합류하며 교직으로 돌아간다고 했으므로 교수직을 수락했음을 알 수 있다.\n오답 분석: (A): 뉴질랜드 출신이라는 언급이 없다. / (B): 기부는 동료들이 선물 비용으로 하는 것이다. / (C): Woloch 씨는 선물 관련 연락처일 뿐이다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 관해"], "dr": ["명사", "박사"], "decker": ["고유명사", "Decker(인명)"]}}], "vocab": "faculty 명 교수진 / farewell party 명 송별회 / accomplishment 명 업적 / present A with B 구 A에게 B를 증정하다 / register 동 등록하다 / donation 명 기부(금) / extension 명 내선 번호 / promotion 명 승진 || Paraphrase: A farewell party ~ will be held → invite employees to a celebration joining the engineering faculty ~ returns to teaching → she has accepted a teaching position", "g": {"to": ["전치사", "수신 / to부정사"], "research": ["명사", "연구"], "and": ["접속사", "그리고"], "development": ["명사", "개발"], "staff": ["명사", "직원"], "from": ["전치사", "발신"], "laurel": ["고유명사", "Laurel(인명)"], "altmann": ["고유명사", "Altmann(인명)"], "date": ["명사", "날짜"], "july": ["명사", "7월"], "10": ["숫자", "10"], "subject": ["명사", "제목"], "dr": ["명사", "박사"], "decker": ["고유명사", "Decker(인명)"], "dear": ["형용사", "친애하는"], "colleagues": ["명사", "동료", "colleague"], "after": ["전치사", "~ 후에"], "fifteen": ["숫자", "열다섯"], "years": ["명사", "년", "year"], "at": ["전치사", "~에(서)"], "marabay": ["고유명사", "Marabay(회사명)"], "labs": ["고유명사", "Labs(회사명 일부)"], "senior": ["형용사", "선임의"], "scientist": ["명사", "과학자"], "rosamond": ["고유명사", "Rosamond(인명)"], "is": ["동사", "~이다", "be"], "leaving": ["현재분사", "떠나는", "leave"], "move": ["동사", "이주하다"], "new": ["고유명사", "(New Zealand) 뉴"], "zealand": ["고유명사", "(New Zealand) 뉴질랜드"], "where": ["관계사", "그곳에서"], "she": ["대명사", "그녀"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "joining": ["현재분사", "합류하는", "join"], "the": ["관사", "그"], "engineering": ["명사", "공학"], "faculty": ["명사", "교수진, 학부"], "wareham": ["고유명사", "Wareham(대학명)"], "university": ["명사", "대학교"], "a": ["관사", "하나의"], "farewell": ["명사", "작별(farewell party 송별회)"], "party": ["명사", "파티"], "for": ["전치사", "~을 위해"], "held": ["과거분사", "열리는", "hold"], "bistro": ["고유명사", "Bistro(식당명 일부)"], "georgiana": ["고유명사", "Georgiana(식당명 일부)"], "on": ["전치사", "~에"], "24": ["숫자", "24"], "7": ["숫자", "7"], "p.m": ["명사", "오후"], "we": ["대명사", "우리"], "celebrating": ["현재분사", "축하하는", "celebrate"], "her": ["대명사", "그녀의"], "accomplishments": ["명사", "업적", "accomplishment"], "presenting": ["현재분사", "(present A with B) 증정하는", "present"], "with": ["전치사", "(present A with B) B를"], "gift": ["명사", "선물"], "wish": ["동사", "빌다(wish ~ well 잘되기를 빌다)"], "well": ["부사", "잘"], "as": ["접속사", "~할 때"], "returns": ["동사", "돌아가다", "return"], "teaching": ["명사", "교직, 가르치는 일"], "one": ["대명사", "하나"], "of": ["전치사", "~의"], "passions": ["명사", "열정", "passion"], "indicate": ["동사", "알리다, 표시하다"], "that": ["접속사", "~라는 것(so that)"], "you": ["대명사", "당신(들)"], "plan": ["동사", "계획하다"], "attend": ["동사", "참석하다"], "please": ["부사", "~해 주십시오"], "register": ["동사", "등록하다"], "www.marabaylab4.com/events/4591": ["고유명사", "웹사이트 주소"], "so": ["접속사", "(so that) ~하도록"], "know": ["동사", "알다"], "how": ["부사", "얼마나"], "many": ["형용사", "많은"], "people": ["명사", "사람들"], "expect": ["동사", "예상하다"], "if": ["접속사", "만약 ~라면"], "would": ["조동사", "~할 것이다"], "like": ["동사", "(would like to) ~하고 싶다"], "make": ["동사", "하다(make a donation 기부하다)"], "donation": ["명사", "기부(금)"], "toward": ["전치사", "~을 위해, ~에 보태어"], "contact": ["동사", "연락하다"], "jake": ["고유명사", "Jake(인명)"], "woloch": ["고유명사", "Woloch(인명)"], "extension": ["명사", "내선 번호"], "256": ["숫자", "256"], "kind": ["형용사", "친절한"], "regards": ["명사", "안부(맺음말)"], "administrative": ["형용사", "행정의"], "manager": ["명사", "관리자"]}}, {"range": "156-157", "passage": "Julio Sanchez [4:02 P.M.] I think we're going to have to postpone the meeting tomorrow morning.\nSonia McCauley [4:04 P.M.] We can't! We need it to prepare for the conference.\nJulio Sanchez [4:06 P.M.] Well, Mr. Nassar just called me. His flight was delayed, and he won't be back until late tomorrow night.\nSonia McCauley [4:08 P.M.] Guess what ― I just got a text from Ellen Keskinen. She's giving a presentation to clients tomorrow morning. She isn't available until the afternoon, and I'm booked then. We all really need to meet, though.\nJulio Sanchez [4:12 P.M.] The conference is on Friday afternoon. We'll be travelling on Friday morning, so Friday won't work.\nSonia McCauley [4:13 P.M.] Let's see. It's already Tuesday afternoon now. What about Thursday? Same time.\nJulio Sanchez [4:14 P.M.] I'll check everyone's calendars.", "tr": "Julio Sanchez [오후 4:02] 내일 오전 회의를 미뤄야 할 것 같아요.\nSonia McCauley [오후 4:04] 안 돼요! 학회 준비를 위해 그 회의가 필요해요.\nJulio Sanchez [오후 4:06] 그런데 Nassar 씨가 방금 전화했어요. 항공편이 지연돼서 내일 밤 늦게야 돌아온대요.\nSonia McCauley [오후 4:08] 그런데요, 방금 Ellen Keskinen에게서 문자를 받았어요. 내일 오전에 고객 대상 발표가 있대요. 오후에나 시간이 되는데 저는 그때 일정이 있어요. 그래도 우리 모두 꼭 만나야 해요.\nJulio Sanchez [오후 4:12] 학회는 금요일 오후예요. 금요일 오전에는 이동해야 하니 금요일은 안 됩니다.\nSonia McCauley [오후 4:13] 봅시다. 지금 벌써 화요일 오후네요. 목요일은 어때요? 같은 시간에요.\nJulio Sanchez [오후 4:14] 모두의 일정을 확인해 볼게요.", "questions": [{"no": 156, "q": "Why must Ms. McCauley and Mr. Sanchez have a meeting?", "options": ["To plan for an event", "To respond to an unexpected request", "To select staff for a new project", "To prepare for a client visit"], "answer": 0, "explain": "정답 (A) To plan for an event\n지문 개요: 학회 준비 회의를 잡으려는 두 직원이 참석자들의 일정 문제로 회의를 목요일로 옮기려고 논의하는 대화다.\n정답 근거: 학회 준비를 위해 회의가 필요하다고 했으므로 행사를 준비하기 위한 회의다.\n오답 분석: (B): 예상치 못한 요청에 대응하는 것이 아니다. / (C): 새 프로젝트 인력 선발이 아니다. / (D): 고객 방문 준비가 아니라 학회 준비다.", "g": {"why": ["부사", "왜"], "must": ["조동사", "~해야 한다"], "ms": ["명사", "~씨(여성)"], "mccauley": ["고유명사", "McCauley(인명)"], "and": ["접속사", "그리고"], "mr": ["명사", "~씨(남성)"], "sanchez": ["고유명사", "Sanchez(인명)"], "have": ["동사", "(회의를) 하다"], "a": ["관사", "하나의"], "meeting": ["명사", "회의"]}}, {"no": 157, "q": "At 4:13 P.M., what does Ms. McCauley imply when she writes, “Same time”?", "options": ["She realizes the meeting will conflict with a conference.", "She is concerned that Ms. Keskinen will not be available to meet.", "She would like the group to meet in the morning on Thursday.", "She thinks the meeting will last for one hour."], "answer": 2, "explain": "정답 (C) She would like the group to meet in the morning on Thursday.\n정답 근거: 원래 회의가 내일 오전이었고 목요일을 제안하며 같은 시간이라고 했으므로 목요일 오전을 뜻한다.\n오답 분석: (A): 학회는 금요일 오후여서 목요일과 겹치지 않는다. / (B): Keskinen 씨의 일정 문제는 내일에 한정된 이야기다. / (D): 회의 길이를 말한 것이 아니다.", "g": {"at": ["전치사", "~에"], "4:13": ["숫자", "4:13"], "p.m": ["명사", "오후"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문·부정 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "mccauley": ["고유명사", "McCauley(인명)"], "imply": ["동사", "암시하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "same": ["형용사", "같은"], "time": ["명사", "시간"]}}], "vocab": "postpone 동 연기하다 / delayed 형 지연된 / booked 형 일정이 차 있는 / work 동 (일정이) 되다, 가능하다 / conflict with 구 ~와 겹치다 / unexpected 형 예상치 못한 || Paraphrase: We need it to prepare for the conference → to plan for an event 원래 회의가 오전 → What about Thursday? Same time → meet in the morning on Thursday", "g": {"julio": ["고유명사", "Julio(인명)"], "sanchez": ["고유명사", "Sanchez(인명)"], "4:02": ["숫자", "4:02"], "p.m": ["명사", "오후"], "i": ["대명사", "나"], "think": ["동사", "생각하다"], "we're": ["대명사", "우리는 ~이다(we are)"], "going": ["현재분사", "(be going to) ~할 예정인", "go"], "to": ["to부정사", "~해야 하다(have to) / ~하기 위해"], "have": ["동사", "(have to) ~해야 하다"], "postpone": ["동사", "연기하다"], "the": ["관사", "그"], "meeting": ["명사", "회의"], "tomorrow": ["명사", "내일"], "morning": ["명사", "아침, 오전"], "sonia": ["고유명사", "Sonia(인명)"], "mccauley": ["고유명사", "McCauley(인명)"], "4:04": ["숫자", "4:04"], "we": ["대명사", "우리"], "can't": ["조동사", "~할 수 없다", "can"], "need": ["동사", "필요로 하다"], "it": ["대명사", "그것(회의)"], "prepare": ["동사", "준비하다"], "for": ["전치사", "~을 위해"], "conference": ["명사", "학회"], "4:06": ["숫자", "4:06"], "well": ["감탄사", "글쎄, 그런데"], "mr": ["명사", "~씨(남성)"], "nassar": ["고유명사", "Nassar(인명)"], "just": ["부사", "방금"], "called": ["동사", "전화했다", "call"], "me": ["대명사", "나를"], "his": ["대명사", "그의"], "flight": ["명사", "항공편"], "was": ["동사", "~이었다", "be"], "delayed": ["과거분사", "지연된", "delay"], "and": ["접속사", "그리고"], "he": ["대명사", "그"], "won't": ["조동사", "~하지 않을 것이다", "will"], "be": ["동사", "~이다, 되다"], "back": ["부사", "돌아와"], "until": ["전치사", "(not until) ~이 되어서야"], "late": ["부사", "늦게"], "night": ["명사", "밤"], "4:08": ["숫자", "4:08"], "guess": ["동사", "추측하다(Guess what 있잖아요)"], "what": ["대명사", "무엇(What about ~? ~은 어때요?)"], "got": ["동사", "받았다", "get"], "a": ["관사", "하나의"], "text": ["명사", "문자"], "from": ["전치사", "~로부터"], "ellen": ["고유명사", "Ellen(인명)"], "keskinen": ["고유명사", "Keskinen(인명)"], "she's": ["대명사", "그녀는 ~이다(she is)"], "giving": ["현재분사", "(발표를) 하는", "give"], "presentation": ["명사", "발표"], "clients": ["명사", "고객", "client"], "she": ["대명사", "그녀"], "isn't": ["동사", "~이 아니다", "be"], "available": ["형용사", "시간이 되는"], "afternoon": ["명사", "오후"], "i'm": ["대명사", "나는 ~이다(I am)"], "booked": ["형용사", "일정이 차 있는"], "then": ["부사", "그때"], "all": ["대명사", "모두"], "really": ["부사", "정말"], "meet": ["동사", "만나다"], "though": ["부사", "그래도, 하지만"], "4:12": ["숫자", "4:12"], "is": ["동사", "~이다", "be"], "on": ["전치사", "~에"], "friday": ["명사", "금요일"], "we'll": ["대명사", "우리는 ~할 것이다(we will)"], "travelling": ["현재분사", "이동하는", "travel"], "so": ["접속사", "그래서"], "work": ["동사", "(일정이) 되다, 가능하다"], "4:13": ["숫자", "4:13"], "let's": ["동사", "~하자(let us)"], "see": ["동사", "보다, 생각해 보다"], "it's": ["대명사", "그것은 ~이다(it is)"], "already": ["부사", "벌써"], "tuesday": ["명사", "화요일"], "now": ["부사", "지금"], "about": ["전치사", "(What about) ~은 어때요"], "thursday": ["명사", "목요일"], "same": ["형용사", "같은"], "time": ["명사", "시간"], "4:14": ["숫자", "4:14"], "i'll": ["대명사", "나는 ~할 것이다(I will)"], "check": ["동사", "확인하다"], "everyone's": ["대명사", "모든 사람의", "everyone"], "calendars": ["명사", "일정표", "calendar"]}}, {"range": "147-148", "passage": "To: Wayan Cahyo\nFrom: Adi Athletic Club\nDate: March 10\nSubject: Acknowledgment\nDear Mr. Cahyo,\nThis is to acknowledge receipt of your letter dated March 5. Your request has been processed. Your athletic club membership is scheduled to end on the date indicated below. You are welcome to use our facilities and attend group classes until then. Please be sure to clear out your locker of any personal belongings by this deadline.\nTermination effective: March 31\nThank you. Jordi Sommers, Customer Service Representative", "tr": "수신: Wayan Cahyo / 발신: Adi Athletic Club / 날짜: 3월 10일 / 제목: 접수 확인\nCahyo 씨께,\n3월 5일 자 서신의 접수를 확인해 드립니다. 요청은 처리되었습니다. 귀하의 운동 클럽 회원 자격은 아래 표기된 날짜에 종료될 예정입니다. 그때까지는 시설을 이용하고 단체 수업에 참여하실 수 있습니다. 이 기한까지 사물함의 개인 물품을 반드시 비워 주십시오.\n해지 적용일: 3월 31일\n감사합니다. 고객 서비스 담당 Jordi Sommers", "sub": "기출독해 8회", "questions": [{"no": 147, "q": "What is the purpose of the e-mail?", "options": ["To correct some information", "To offer a membership discount", "To promote a new group class", "To confirm a cancellation"], "answer": 3, "explain": "정답 (D) To confirm a cancellation\n지문 개요: 운동 클럽이 회원의 해지 요청 처리 결과와 종료일, 사물함 정리 요청을 알리는 확인 이메일이다.\n정답 근거: 회원 해지 요청이 처리되었고 종료일이 정해졌음을 알리므로 해지를 확인해 주는 것이 목적이다.\n오답 분석: (A): 정보를 정정하는 내용이 아니다. / (B): 할인 제안이 아니다. / (C): 새 수업 홍보가 아니다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "e-mail": ["명사", "이메일"]}}, {"no": 148, "q": "What must Mr. Cahyo do by March 31?", "options": ["Mail a check", "Empty a locker", "Write to an instructor", "Call Mr. Sommers"], "answer": 1, "explain": "정답 (B) Empty a locker\n정답 근거: 해지일인 3월 31일까지 사물함의 개인 물품을 비우라고 요청한다.\n오답 분석: (A): 수표 발송 요구가 없다. / (C): 강사에게 편지를 쓰라는 안내가 없다. / (D): 담당자에게 전화하라는 요구는 없다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "must": ["조동사", "~해야 한다"], "mr": ["명사", "~씨(남성)"], "cahyo": ["고유명사", "Cahyo(인명)"], "do": ["동사", "하다"], "by": ["전치사", "~까지"], "march": ["명사", "3월"], "31": ["숫자", "31"]}}], "vocab": "acknowledge receipt of 구 ~의 수령을 확인하다 / process 동 처리하다 / be scheduled to do 구 ~할 예정이다 / facility 명 시설 / clear out 구 비우다 / personal belongings 명 개인 소지품 / termination 명 해지, 종료 / effective 형 효력이 발생하는 || Paraphrase: Your request has been processed Termination effective → confirm a cancellation clear out your locker of any personal belongings → empty a locker", "g": {"to": ["전치사", "수신 / to부정사"], "wayan": ["고유명사", "Wayan(인명)"], "cahyo": ["고유명사", "Cahyo(인명)"], "from": ["전치사", "발신"], "adi": ["고유명사", "Adi(클럽명)"], "athletic": ["형용사", "운동의"], "club": ["명사", "클럽"], "date": ["명사", "날짜"], "march": ["명사", "3월"], "10": ["숫자", "10"], "subject": ["명사", "제목"], "acknowledgment": ["명사", "접수 확인"], "dear": ["형용사", "친애하는"], "mr": ["명사", "~씨(남성)"], "this": ["대명사", "이것"], "is": ["동사", "~이다", "be"], "acknowledge": ["동사", "(수령을) 확인하다"], "receipt": ["명사", "수령, 접수"], "of": ["전치사", "~의 / (clear A of B) A에서 B를"], "your": ["대명사", "당신의"], "letter": ["명사", "편지, 서신"], "dated": ["과거분사", "~일 자의", "date"], "5": ["숫자", "5"], "request": ["명사", "요청"], "has": ["조동사", "(완료) ~했다", "have"], "been": ["과거분사", "~였던", "be"], "processed": ["과거분사", "처리된", "process"], "membership": ["명사", "회원 자격"], "scheduled": ["과거분사", "예정된", "schedule"], "end": ["동사", "끝나다"], "on": ["전치사", "~에"], "the": ["관사", "그"], "indicated": ["과거분사", "명시된", "indicate"], "below": ["부사", "아래에"], "you": ["대명사", "당신(들)"], "are": ["동사", "~이다", "be"], "welcome": ["형용사", "(be welcome to) 마음껏 ~해도 되는"], "use": ["동사", "이용하다"], "our": ["대명사", "우리의"], "facilities": ["명사", "시설", "facility"], "and": ["접속사", "그리고"], "attend": ["동사", "참석하다"], "group": ["명사", "단체"], "classes": ["명사", "수업", "class"], "until": ["전치사", "~까지"], "then": ["부사", "그때"], "please": ["부사", "~해 주십시오"], "be": ["동사", "~이다, 되다"], "sure": ["형용사", "(be sure to) 반드시 ~하다"], "clear": ["동사", "(clear out) 비우다"], "out": ["부사", "(clear out) 비우다"], "locker": ["명사", "사물함"], "any": ["한정사", "어떤"], "personal": ["형용사", "개인의"], "belongings": ["명사", "소지품", "belonging"], "by": ["전치사", "~까지"], "deadline": ["명사", "마감"], "termination": ["명사", "해지"], "effective": ["형용사", "효력이 발생하는"], "31": ["숫자", "31"], "thank": ["동사", "감사하다"], "jordi": ["고유명사", "Jordi(인명)"], "sommers": ["고유명사", "Sommers(인명)"], "customer": ["명사", "고객"], "service": ["명사", "서비스"], "representative": ["명사", "담당 직원"]}}, {"range": "149-150", "passage": "Consumer Review: Outdoor Lighting Fixtures · Review posted by: Tony Wivell\nMy neighbor pays $30 every month for size-D batteries to operate his Dotono motion-activated lights. Even though they emit a lot of light, the cost of operation surprised me. As an alternative, I thought I'd try out F&Q lights, which have a money-back guarantee. To experiment, I purchased only one outdoor wall light just to test it out. I put it out in the sun to charge up for three hours, and that was enough for it to stay lit the whole night! It was also very sensitive to any motion. I've made my choice, and it wasn't even close. I'm sure I'll be happy with more.", "tr": "소비자 후기: 야외 조명 기구 · 작성자: Tony Wivell\n이웃은 Dotono 동작 감지 조명을 작동시키려고 매달 30달러를 D형 건전지에 씁니다. 빛은 많이 나오지만 운영 비용이 놀라웠습니다. 대안으로 환불 보장이 있는 F&Q 조명을 시험해 보기로 했습니다. 실험 삼아 야외 벽등 하나만 사서 시험했습니다. 햇볕에 세 시간 충전해 두었더니 밤새 켜져 있기에 충분했습니다! 동작에도 매우 민감했습니다. 저는 선택을 마쳤고, 비교조차 되지 않았습니다. 더 들여도 만족할 것이라 확신합니다.", "sub": "기출독해 8회", "questions": [{"no": 149, "q": "What is suggested about F&Q Lights?", "options": ["They cannot be used outside.", "They run on solar power.", "They are expensive to operate.", "They are not motion activated."], "answer": 1, "explain": "정답 (B) They run on solar power.\n지문 개요: 건전지식 조명과 충전식 조명을 비교해 사용해 본 소비자가 충전식 제품의 성능에 만족한다고 밝힌 후기다.\n정답 근거: 햇볕에 세 시간 충전하니 밤새 켜졌다고 했으므로 태양광으로 작동함을 알 수 있다.\n오답 분석: (A): 야외 벽등으로 사용했다고 밝힌다. / (C): 비싼 운영비는 건전지식 제품의 문제다. / (D): 동작에 매우 민감했다고 한다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "suggested": ["과거분사", "암시된", "suggest"], "about": ["전치사", "~에 관해"], "f&q": ["고유명사", "F&Q(상표명)"], "lights": ["명사", "조명", "light"]}}, {"no": 150, "q": "What did Mr. Wivell probably do after writing his review?", "options": ["He asked F&Q for a refund.", "He complained to his neighbor.", "He bought additional F&Q lights.", "He tested a Dotono light."], "answer": 2, "explain": "정답 (C) He bought additional F&Q lights.\n정답 근거: 선택을 마쳤고 더 들여도 만족할 것이라고 했으므로 추가 구매했을 가능성이 크다.\n오답 분석: (A): 환불 보장은 언급했으나 만족했으므로 환불 요청은 어울리지 않는다. / (B): 이웃에게 항의한다는 내용이 없다. / (D): 이미 이웃의 제품을 관찰했을 뿐 직접 시험하지 않는다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "did": ["조동사", "(과거 의문·부정)", "do"], "mr": ["명사", "~씨(남성)"], "wivell": ["고유명사", "Wivell(인명)"], "probably": ["부사", "아마"], "do": ["조동사", "(의문·부정 조동사)"], "after": ["전치사", "~ 후에"], "writing": ["동명사", "쓰는 것", "write"], "his": ["대명사", "그의"], "review": ["명사", "검토"]}}], "vocab": "motion-activated 형 동작 감지식의 / emit 동 (빛을) 내다 / alternative 명 대안 / money-back guarantee 명 환불 보장 / charge up 구 충전하다 / stay lit 구 계속 켜져 있다 / sensitive 형 민감한 / run on 구 ~으로 작동하다 || Paraphrase: put it out in the sun to charge up → they run on solar power I'm sure I'll be happy with more → he bought additional F&Q lights", "g": {"consumer": ["명사", "소비자"], "review": ["명사", "후기"], "outdoor": ["형용사", "야외의"], "lighting": ["명사", "조명"], "fixtures": ["명사", "기구, 설비", "fixture"], "posted": ["과거분사", "게시된", "post"], "by": ["전치사", "~에 의해"], "tony": ["고유명사", "Tony(인명)"], "wivell": ["고유명사", "Wivell(인명)"], "my": ["대명사", "나의"], "neighbor": ["명사", "이웃"], "pays": ["동사", "지불하다", "pay"], "$30": ["숫자", "$30"], "every": ["한정사", "모든"], "month": ["명사", "달"], "for": ["전치사", "~에 대해 / ~ 동안"], "size-d": ["형용사", "D형의"], "batteries": ["명사", "건전지", "battery"], "to": ["to부정사", "~하기 위해 / ~하는"], "operate": ["동사", "작동시키다"], "his": ["대명사", "그의"], "dotono": ["고유명사", "Dotono(상표명)"], "motion-activated": ["형용사", "동작 감지식의"], "lights": ["명사", "조명", "light"], "even": ["부사", "심지어(even though ~이지만)"], "though": ["부사", "그래도, 하지만"], "they": ["대명사", "그들"], "emit": ["동사", "(빛을) 내다"], "a": ["관사", "하나의"], "lot": ["명사", "(a lot of) 많은"], "of": ["전치사", "~의"], "light": ["명사", "빛"], "the": ["관사", "그"], "cost": ["명사", "비용"], "operation": ["명사", "작동, 운영"], "surprised": ["동사", "놀라게 했다", "surprise"], "me": ["대명사", "나를"], "as": ["전치사", "~로서"], "an": ["관사", "하나의"], "alternative": ["명사", "대안"], "i": ["대명사", "나"], "thought": ["동사", "생각했다", "think"], "i'd": ["대명사", "나는 ~할 것이다(I would)"], "try": ["동사", "(try out) 시험해 보다"], "out": ["부사", "(try out / put out) 시험 삼아, 밖에"], "f&q": ["고유명사", "F&Q(상표명)"], "which": ["관계사", "그런데 그것은"], "have": ["동사", "가지고 있다"], "money-back": ["형용사", "환불의"], "guarantee": ["명사", "보장"], "experiment": ["동사", "실험하다"], "purchased": ["동사", "구매했다", "purchase"], "only": ["부사", "오직, ~만"], "one": ["숫자", "하나"], "wall": ["명사", "벽"], "just": ["부사", "막, 단지"], "test": ["동사", "(test out) 시험하다"], "it": ["대명사", "그것(조명)"], "put": ["동사", "두었다", "put"], "in": ["전치사", "~에(서)"], "sun": ["명사", "햇볕"], "charge": ["동사", "(charge up) 충전하다"], "up": ["부사", "(charge up) 가득"], "three": ["숫자", "셋"], "hours": ["명사", "시간", "hour"], "and": ["접속사", "그리고"], "that": ["대명사", "그것"], "was": ["동사", "~이었다", "be"], "enough": ["형용사", "충분한"], "stay": ["동사", "계속 ~하다"], "lit": ["과거분사", "켜진", "light"], "whole": ["형용사", "전체의"], "night": ["명사", "밤"], "also": ["부사", "또한"], "very": ["부사", "매우"], "sensitive": ["형용사", "민감한"], "any": ["한정사", "어떤"], "motion": ["명사", "움직임"], "i've": ["대명사", "나는 ~했다(I have)"], "made": ["과거분사", "(선택을) 한", "make"], "choice": ["명사", "선택"], "wasn't": ["동사", "~이 아니었다", "be"], "close": ["형용사", "(우열이) 비슷한, 막상막하의"], "i'm": ["대명사", "나는 ~이다(I am)"], "sure": ["형용사", "확신하는"], "i'll": ["대명사", "나는 ~할 것이다(I will)"], "be": ["동사", "~이다, 되다"], "happy": ["형용사", "만족하는"], "with": ["전치사", "~에"], "more": ["대명사", "더 많은 것"]}}, {"range": "151-152", "passage": "To: a.thompson@pepperfam.com\nFrom: customerservice@dixons_clothing.com\nDate: November 4\nSubject: Your recent order\nDear Mr. Thompson,\nOur records show that your Dixon's Clothing order number 5409281 has been delivered.\nItem: Canvas Rain-Resistant Jacket (Men's): $85.00\nShipping Fee: $4.50\nTotal: $89.50\nIt's important to us to know that you're happy with your item. Therefore, if you have any questions, comments, or concerns about it, call us at 555-0142, Monday through Friday between 8:00 A.M. and 7:00 P.M., and Saturday and Sunday between 10:00 A.M. and 5:00 P.M. You can also e-mail us at customerservice@dixons_clothing.com. We look forward to serving you again.\nSincerely, Customer Service Department, Dixon's Clothing", "tr": "수신: a.thompson@pepperfam.com / 발신: customerservice@dixons_clothing.com / 날짜: 11월 4일 / 제목: 최근 주문\nThompson 씨께,\n기록에 따르면 Dixon's Clothing 주문 번호 5409281이 배송 완료되었습니다.\n품목: 방수 캔버스 재킷(남성용) 85.00달러 / 배송비 4.50달러 / 합계 89.50달러\n고객님이 제품에 만족하시는지가 저희에게 중요합니다. 따라서 제품에 관해 질문, 의견, 우려가 있으시면 월요일부터 금요일 오전 8시~오후 7시, 토요일과 일요일 오전 10시~오후 5시에 555-0142로 전화 주십시오. customerservice@dixons_clothing.com으로 이메일을 보내셔도 됩니다. 다시 모실 수 있기를 기대합니다.\nDixon's Clothing 고객 서비스부 드림", "sub": "기출독해 8회", "questions": [{"no": 151, "q": "What is a purpose of the e-mail?", "options": ["To notify a customer of a late delivery", "To confirm a request for an exchange", "To request payment for an order", "To tell a customer how to give feedback"], "answer": 3, "explain": "정답 (D) To tell a customer how to give feedback\n지문 개요: 의류 판매점이 주문 배송 완료를 알리고 문의나 의견을 전할 수 있는 연락 방법과 운영 시간을 안내하는 이메일이다.\n정답 근거: 제품에 관한 질문·의견·우려를 전달할 전화번호와 이메일 주소를 안내하고 있으므로 의견 전달 방법을 알리는 것이 목적이다.\n오답 분석: (A): 배송 지연이 아니라 배송 완료 안내다. / (B): 교환 요청 확인이 아니다. / (C): 결제는 이미 이루어졌다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "a": ["관사", "하나의"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"]}}, {"no": 152, "q": "What is indicated about Dixon's Clothing?", "options": ["It has several store locations.", "It offers free shipping.", "Its customer service representatives are available daily.", "Its Web site features product reviews from customers."], "answer": 2, "explain": "정답 (C) Its customer service representatives are available daily.\n정답 근거: 평일과 주말 모두 상담 가능한 시간이 제시되어 있으므로 매일 응대함을 알 수 있다.\n오답 분석: (A): 매장 수에 관한 언급이 없다. / (B): 배송비 4.50달러가 청구되었다. / (D): 웹사이트 후기 기능은 언급되지 않는다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "indicated": ["과거분사", "명시된", "indicate"], "about": ["전치사", "~에 관해"], "dixon's": ["고유명사", "Dixon의(상호)"], "clothing": ["명사", "의류"]}}], "vocab": "record 명 기록 / rain-resistant 형 방수의 / shipping fee 명 배송비 / concern 명 우려, 문의 / serve 동 응대하다 / notify 동 알리다 / representative 명 상담원, 직원 / daily 부 매일 || Paraphrase: questions, comments, or concerns ~ call us e-mail us → tell a customer how to give feedback 월~금 + 토·일 전화 응대 → representatives are available daily", "g": {"to": ["전치사", "수신 / to부정사, ~에게"], "a.thompson@pepperfam.com": ["고유명사", "이메일 주소"], "from": ["전치사", "발신"], "customerservice@dixons_clothing.com": ["고유명사", "이메일 주소"], "date": ["명사", "날짜"], "november": ["명사", "11월"], "4": ["숫자", "4"], "subject": ["명사", "제목"], "your": ["대명사", "당신의"], "recent": ["형용사", "최근의"], "order": ["명사", "주문"], "dear": ["형용사", "친애하는"], "mr": ["명사", "~씨(남성)"], "thompson": ["고유명사", "Thompson(인명)"], "our": ["대명사", "우리의"], "records": ["명사", "기록", "record"], "show": ["동사", "보여 주다"], "that": ["접속사", "~라는 것"], "dixon's": ["고유명사", "Dixon의(상호)"], "clothing": ["명사", "의류"], "number": ["명사", "번호"], "5409281": ["숫자", "5409281"], "has": ["조동사", "(완료) ~했다", "have"], "been": ["과거분사", "~였던", "be"], "delivered": ["과거분사", "배송된", "deliver"], "item": ["명사", "품목, 제품"], "canvas": ["명사", "캔버스(천)"], "rain-resistant": ["형용사", "방수의"], "jacket": ["명사", "재킷"], "men's": ["명사", "남성용", "man"], "$85.00": ["숫자", "$85.00"], "shipping": ["명사", "배송"], "fee": ["명사", "요금"], "$4.50": ["숫자", "$4.50"], "total": ["명사", "합계"], "$89.50": ["숫자", "$89.50"], "it's": ["대명사", "(가주어) ~은 ~이다(it is)"], "important": ["형용사", "중요한"], "us": ["대명사", "우리를"], "know": ["동사", "알다"], "you're": ["대명사", "당신은 ~이다(you are)"], "happy": ["형용사", "만족하는"], "with": ["전치사", "~에"], "therefore": ["부사", "따라서"], "if": ["접속사", "만약 ~라면"], "you": ["대명사", "당신(들)"], "have": ["조동사", "(완료) ~했다"], "any": ["한정사", "어떤"], "questions": ["명사", "질문", "question"], "comments": ["명사", "의견", "comment"], "or": ["접속사", "또는"], "concerns": ["명사", "우려", "concern"], "about": ["전치사", "~에 관해"], "it": ["대명사", "그것(제품)"], "call": ["동사", "전화하다"], "at": ["전치사", "~로"], "555-0142": ["숫자", "555-0142"], "monday": ["명사", "월요일"], "through": ["전치사", "(Monday through Friday) ~까지"], "friday": ["명사", "금요일"], "between": ["전치사", "~ 사이에"], "8:00": ["숫자", "8:00"], "a.m": ["명사", "오전"], "and": ["접속사", "그리고"], "7:00": ["숫자", "7:00"], "p.m": ["명사", "오후"], "saturday": ["명사", "토요일"], "sunday": ["명사", "일요일"], "10:00": ["숫자", "10:00"], "5:00": ["숫자", "5:00"], "can": ["조동사", "~할 수 있다"], "also": ["부사", "또한"], "e-mail": ["동사", "이메일을 보내다"], "we": ["대명사", "우리"], "look": ["동사", "(look forward to) 고대하다"], "forward": ["부사", "(look forward to) 앞으로"], "serving": ["동명사", "응대하는 것", "serve"], "again": ["부사", "다시"], "sincerely": ["부사", "진심으로(맺음말)"], "customer": ["명사", "고객"], "service": ["명사", "서비스"], "department": ["명사", "부서"]}}, {"range": "153-154", "passage": "Leann Oliver (9:20 A.M.) Hi, Rafael. Will you be coming to the hiring committee meeting this afternoon?\nRafael Sauceda (9:21 A.M.) I wasn't planning to. Do you need me there?\nLeann Oliver (9:22 A.M.) We had more candidates apply for the job than we anticipated. We need to decide who to interview, and your expertise would be very helpful.\nRafael Sauceda (9:23 A.M.) I'll be happy to help. It's at 4, right?\nLeann Oliver (9:24 A.M.) Exactly. In conference room B. I'll see you there. Thanks.", "tr": "Leann Oliver [오전 9:20] 안녕하세요, Rafael. 오늘 오후 채용 위원회 회의에 오시나요?\nRafael Sauceda [오전 9:21] 갈 생각은 아니었어요. 제가 필요한가요?\nLeann Oliver [오전 9:22] 예상보다 많은 지원자가 그 자리에 지원했어요. 누구를 면접할지 정해야 하는데 당신의 전문성이 큰 도움이 될 거예요.\nRafael Sauceda [오전 9:23] 기꺼이 돕겠습니다. 4시죠?\nLeann Oliver [오전 9:24] 맞아요. B 회의실입니다. 그때 봬요. 감사합니다.", "sub": "기출독해 8회", "questions": [{"no": 153, "q": "What is the purpose of the meeting mentioned by Ms. Oliver?", "options": ["To interview a candidate for an open position", "To approve a job announcement", "To consider applicants for a job", "To select members for a hiring committee"], "answer": 2, "explain": "정답 (C) To consider applicants for a job\n지문 개요: 예상보다 많은 지원자가 몰려 면접 대상자를 정해야 하는 상황에서 동료에게 회의 참석을 부탁하는 대화다.\n정답 근거: 누구를 면접할지 정해야 한다고 했으므로 지원자를 검토하는 회의다.\n오답 분석: (A): 아직 면접 대상자를 정하는 단계다. / (B): 채용 공고 승인이 아니다. / (D): 위원 선발이 아니라 지원자 검토다.", "sub": "기출독해 8회", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "meeting": ["명사", "회의"], "mentioned": ["과거분사", "언급된", "mention"], "by": ["전치사", "~에 의해"], "ms": ["명사", "~씨(여성)"], "oliver": ["고유명사", "Oliver(인명)"]}}, {"no": 154, "q": "At 9:24 A.M., what does Ms. Oliver most likely mean when she writes, “Exactly”?", "options": ["The meeting room is on the fourth floor.", "The meeting is scheduled for 4:00 P.M.", "Four people will attend the meeting.", "The committee will meet four times."], "answer": 1, "explain": "정답 (B) The meeting is scheduled for 4:00 P.M.\n정답 근거: 상대가 회의가 4시인지 확인한 데 대한 대답이므로 오후 4시가 맞다는 뜻이다.\n오답 분석: (A): 층수가 아니라 시각을 확인한 것이다. / (C): 참석 인원 이야기가 아니다. / (D): 회의 횟수를 말한 것이 아니다.", "sub": "기출독해 8회", "g": {"at": ["전치사", "~에"], "9:24": ["숫자", "9:24"], "a.m": ["명사", "오전"], "what": ["대명사", "무엇"], "does": ["조동사", "(의문·부정 조동사)", "do"], "ms": ["명사", "~씨(여성)"], "oliver": ["고유명사", "Oliver(인명)"], "most": ["부사", "가장"], "likely": ["부사", "아마도(most likely)"], "mean": ["동사", "의미하다"], "when": ["접속사", "~할 때"], "she": ["대명사", "그녀"], "writes": ["동사", "쓰다", "write"], "exactly": ["부사", "바로 그렇다, 정확히"]}}], "vocab": "hiring committee 명 채용 위원회 / candidate 명 지원자 / apply for 구 ~에 지원하다 / anticipate 동 예상하다 / expertise 명 전문 지식 / applicant 명 지원자 / consider 동 검토하다 || Paraphrase: decide who to interview → consider applicants for a job It's at 4, right? → Exactly → the meeting is scheduled for 4:00 P.M.", "g": {"leann": ["고유명사", "Leann(인명)"], "oliver": ["고유명사", "Oliver(인명)"], "9:20": ["숫자", "9:20"], "a.m": ["명사", "오전"], "hi": ["감탄사", "안녕하세요"], "rafael": ["고유명사", "Rafael(인명)"], "will": ["조동사", "~할 것이다"], "you": ["대명사", "당신(들)"], "