insert into content(key,data,updated_at) values('sec:a2-r5-p5',$mkd${"id": "a2-r5-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 5, "level": "중급", "title": "A급 과제 5회 · PART 5 (문법 9·10회)", "notes": [], "items": [{"no": 101, "q": "There are several gym lockers available for _____ members to rent.", "options": ["we", "our", "ours", "ourselves"], "answer": 1, "explain": "정답 (B) our\n해석: 회원들이 대여할 수 있는 체육관 사물함이 여러 개 있다.\n정답 근거: 빈칸 뒤에 명사 members가 있으므로 명사 앞 소유격 자리다.\n오답 분석: (A) we: 주격은 명사를 꾸밀 수 없다. / (C) ours: 소유대명사 뒤에는 명사가 올 수 없다. / (D) ourselves: 재귀대명사는 명사를 수식하지 못한다.", "translation": "회원들이 대여할 수 있는 체육관 사물함이 여러 개 있다.", "vocab": "available 형 이용 가능한 / rent 동 빌리다 / our 소유격 우리의", "g": {"there": ["부사", "(there is) ~이 있다"], "are": ["동사", "~이다, 있다", "be"], "several": ["형용사", "몇몇의"], "gym": ["명사", "체육관"], "lockers": ["명사", "사물함들", "locker"], "available": ["형용사", "이용 가능한"], "for": ["전치사", "~을 위해, ~에 대해"], "members": ["명사", "회원들", "member"], "to": ["to부정사", "~하기 위해, ~하는 / ~로"], "rent": ["동사", "빌리다"]}, "src": "1-"}, {"no": 103, "q": "Ms. Kalish _____ investors to visit her new office last Tuesday.", "options": ["invite", "to invite", "have invited", "invited"], "answer": 3, "explain": "정답 (D) invited\n해석: Kalish 씨는 지난 화요일 투자자들을 새 사무실로 초대했다.\n정답 근거: 문장에 동사가 없고 last Tuesday라는 과거 시점이 있으므로 과거 동사가 정답이다. 뒤에 목적어 investors가 있어 능동태로 맞다.\n오답 분석: (A) invite: 시제가 과거 시점과 맞지 않는다. / (B) to invite: to부정사는 문장의 동사가 될 수 없다. / (C) have invited: 현재완료는 명확한 과거 시점 표현과 함께 쓰지 않는다.", "translation": "Kalish 씨는 지난 화요일 투자자들을 새 사무실로 초대했다.", "vocab": "investor 명 투자자 / invite A to do 구 A에게 ~하도록 청하다", "g": {"ms": ["명사", "~씨(여성)"], "kalish": ["고유명사", "Kalish(인명)"], "investors": ["명사", "투자자들", "investor"], "to": ["to부정사", "~하기 위해, ~하는 / ~로"], "visit": ["동사", "방문하다"], "her": ["대명사", "그녀의, 그녀를"], "new": ["형용사", "새로운"], "office": ["명사", "사무실"], "last": ["형용사", "지난, 마지막의"], "tuesday": ["명사", "화요일"]}, "src": "1-"}, {"no": 105, "q": "The most _____ route to the Mercerville branch is to take Applewood Road on the east side of town.", "options": ["directed", "directs", "directly", "direct"], "answer": 3, "explain": "정답 (D) direct\n해석: Mercerville 지점으로 가는 가장 직통 경로는 시내 동쪽의 Applewood Road를 타는 것이다.\n정답 근거: the most 뒤, 명사 route 앞이므로 최상급을 이루는 형용사 자리다.\n오답 분석: (A) directed: 과거분사로 쓰면 '지시받은 경로'라는 어색한 뜻이 된다. / (B) directs: 동사는 명사를 꾸밀 수 없다. / (C) directly: 부사는 명사를 수식하지 못한다.", "translation": "Mercerville 지점으로 가는 가장 직통 경로는 시내 동쪽의 Applewood Road를 타는 것이다.", "vocab": "direct 형 직행의, 곧장 가는 / route 명 경로 / branch 명 지사", "g": {"the": ["관사", "그"], "most": ["부사", "가장"], "route": ["명사", "경로"], "to": ["to부정사", "~하기 위해, ~하는 / ~로"], "mercerville": ["고유명사", "Mercerville(지명)"], "branch": ["명사", "지점"], "is": ["동사", "~이다", "be"], "take": ["동사", "타다, 받다"], "applewood": ["고유명사", "Applewood(도로명)"], "road": ["명사", "도로"], "on": ["전치사", "~에"], "east": ["형용사", "동쪽의"], "side": ["명사", "쪽"], "of": ["전치사", "~의"], "town": ["명사", "시내"]}, "src": "1-"}, {"no": 108, "q": "Each lamp is _____ constructed of bronze and colored glass.", "options": ["expert", "expertly", "expertise", "experts"], "answer": 1, "explain": "정답 (B) expertly\n해석: 각 램프는 청동과 색유리로 전문가답게 제작되었다.\n정답 근거: be동사와 과거분사 constructed 사이이므로 동사를 꾸미는 부사 자리다.\n오답 분석: (A) expert: 명사·형용사는 be동사와 분사 사이에 올 수 없다. / (C) expertise: 명사도 같은 이유로 불가하다. / (D) experts: 복수 명사여서 부사 자리에 들어갈 수 없다.", "translation": "각 램프는 청동과 색유리로 전문가답게 제작되었다.", "vocab": "expertly 부 전문가답게, 능숙하게 / be constructed of 구 ~으로 제작되다 / bronze 명 청동", "g": {"each": ["한정사", "각각의"], "lamp": ["명사", "램프"], "is": ["동사", "~이다", "be"], "constructed": ["과거분사", "제작된", "construct"], "of": ["전치사", "~의"], "bronze": ["명사", "청동"], "and": ["접속사", "그리고"], "colored": ["형용사", "색이 있는"], "glass": ["명사", "유리"]}, "src": "1-"}, {"no": 110, "q": "Li's Sporting Goods repackaged its surplus tennis balls into bags of ten in an _____ to sell them quickly.", "options": ["attempting", "attempted", "attempts", "attempt"], "answer": 3, "explain": "정답 (D) attempt\n해석: Li's Sporting Goods는 빨리 팔기 위해 남은 테니스공을 열 개들이 봉지로 재포장했다.\n정답 근거: 관사 an 뒤 명사 자리이고 in an attempt to do는 「~하려는 시도로」를 뜻하는 표현이다.\n오답 분석: (A) attempting: 분사는 관사 뒤 명사 자리에 올 수 없다. / (B) attempted: 과거분사도 같은 이유로 불가하다. / (C) attempts: 관사 an이 있으므로 복수 명사는 쓸 수 없다.", "translation": "Li's Sporting Goods는 빨리 팔기 위해 남은 테니스공을 열 개들이 봉지로 재포장했다.", "vocab": "repackage 동 재포장하다 / surplus 형 잉여의 / in an attempt to do 구 ~하려는시도로", "g": {"li's": ["고유명사", "Li's(상호)"], "sporting": ["형용사", "스포츠의"], "goods": ["명사", "용품", "good"], "repackaged": ["동사", "재포장했다", "repackage"], "its": ["대명사", "그것의"], "surplus": ["형용사", "잉여의"], "tennis": ["명사", "테니스"], "balls": ["명사", "공들", "ball"], "into": ["전치사", "~ 안으로, ~로"], "bags": ["명사", "봉지들", "bag"], "of": ["전치사", "~의"], "ten": ["숫자", "10"], "in": ["전치사", "~에, ~에서"], "an": ["관사", "하나의"], "to": ["to부정사", "~하기 위해, ~하는 / ~로"], "sell": ["동사", "팔다"], "them": ["대명사", "그것들을"], "quickly": ["부사", "빨리"]}, "src": "1-"}, {"no": 111, "q": "Full funding for the new laboratory _____ six months after the CEO announced the plans.", "options": ["raised", "had raised", "was raised", "raise"], "answer": 2, "explain": "정답 (C) was raised\n해석: 새 실험실을 위한 전액 자금은 최고 경영자가 계획을 발표한 지 6개월 만에 모금되었다.\n정답 근거: raise는 타동사인데 빈칸 뒤에 목적어가 없고 시간 표현만 있으므로 수동태가 정답이다.\n오답 분석: (A) raised: 능동태라 뒤에 목적어가 있어야 한다. / (B) had raised: 능동태이므로 같은 이유로 불가하다. / (D) raise: 시제와 태가 모두 맞지 않는다.", "translation": "새 실험실을 위한 전액 자금은 최고 경영자가 계획을 발표한 지 6개월 만에 모금되었다.", "vocab": "funding 명 자금 / laboratory 명 실험실 / raise 동 (자금을) 모으다 / announce 동 발표하다", "g": {"full": ["형용사", "전액의, 정가의"], "funding": ["명사", "자금"], "for": ["전치사", "~을 위해, ~에 대해"], "the": ["관사", "그"], "new": ["형용사", "새로운"], "laboratory": ["명사", "실험실"], "six": ["숫자", "6"], "months": ["명사", "개월", "month"], "after": ["접속사", "~한 후에"], "ceo": ["명사", "최고 경영자"], "announced": ["동사", "발표했다", "announce"], "plans": ["명사", "계획", "plan"]}, "src": "1-"}, {"no": 113, "q": "_____ the author nor the illustrator had ever published a book before.", "options": ["Nobody", "None", "Neither", "Nothing"], "answer": 2, "explain": "정답 (C) Neither\n해석: 작가도 삽화가도 전에 책을 출간한 적이 없었다.\n정답 근거: 뒤에 nor가 있으므로 상관접속사 neither A nor B 구조를 이루는 Neither가 정답이다.\n오답 분석: (A) Nobody: nor와 짝을 이루는 표현이 아니다. / (B) None: 뒤에 of가 필요하고 nor와 함께 쓰지 않는다. / (D) Nothing: 사람 명사를 받지 못하고 상관 구조도 이루지 않는다.", "translation": "작가도 삽화가도 전에 책을 출간한 적이 없었다.", "vocab": "neither A nor B 구 A도 B도 아닌 / illustrator 명 삽화가 / publish 동 출판하다", "g": {"the": ["관사", "그"], "author": ["명사", "작가"], "nor": ["접속사", "(neither A nor B) ~도 아닌"], "illustrator": ["명사", "삽화가"], "had": ["조동사", "(과거완료) ~했었다", "have"], "ever": ["부사", "(전에) 한 번이라도"], "published": ["동사", "출판했다", "publish"], "a": ["관사", "하나의"], "book": ["명사", "책"], "before": ["부사", "전에"]}, "src": "1-"}, {"no": 115, "q": "Mr. Shinomoto at the building _____ office informed us that the public address system will be tested at 3:00 P.M. today.", "options": ["manage", "manager", "manageable", "management"], "answer": 3, "explain": "정답 (D) management\n해석: 건물 관리 사무소의 Shinomoto 씨가 오늘 오후 3시에 방송 설비를 점검할 것이라고 우리에게 알려 주었다.\n정답 근거: building과 office 사이에서 복합명사를 이루는 자리이므로 명사 management가 정답이다.\n오답 분석: (A) manage: 동사는 명사 사이에 들어갈 수 없다. / (B) manager: 사람을 뜻해 '건물 관리자 사무소'라는 어색한 결합이 된다. / (C) manageable: 형용사는 building 뒤 복합명사 구조에 맞지 않는다.", "translation": "건물 관리 사무소의 Shinomoto 씨가 오늘 오후 3시에 방송 설비를 점검할 것이라고 우리에게 알려 주었다.", "vocab": "management office 명 관리 사무소 / inform 동 알리다 / public address system 명 구내방송 시스템", "g": {"mr": ["명사", "~씨(남성)"], "shinomoto": ["고유명사", "Shinomoto(인명)"], "at": ["전치사", "~에, ~에서"], "the": ["관사", "그"], "building": ["명사", "건물"], "office": ["명사", "사무실"], "informed": ["동사", "알려 주었다", "inform"], "us": ["대명사", "우리를"], "that": ["접속사", "~라는 것"], "public": ["형용사", "공공의"], "address": ["명사", "(public address) 방송"], "system": ["명사", "시스템, 설비"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "tested": ["과거분사", "점검된", "test"], "3:00": ["숫자", "3시"], "p.m": ["부사", "오후"], "today": ["부사", "오늘"]}, "src": "1-"}, {"no": 121, "q": "Before sending the book to the printer, the publisher decided it required some _____ editing.", "options": ["finalize", "final", "finally", "finalist"], "answer": 1, "explain": "정답 (B) final\n해석: 책을 인쇄소에 보내기 전에 출판사는 최종 편집이 필요하다고 판단했다.\n정답 근거: 명사 editing 앞이므로 형용사 자리다.\n오답 분석: (A) finalize: 동사는 명사를 꾸밀 수 없다. / (C) finally: 부사는 명사를 수식하지 못한다. / (D) finalist: 명사가 연달아 와 뜻이 성립하지 않는다.", "translation": "책을 인쇄소에 보내기 전에 출판사는 최종 편집이 필요하다고 판단했다.", "vocab": "printer 명 인쇄소 / publisher 명 출판사 / final 형 최종의 / editing 명 편집", "g": {"before": ["전치사", "~ 전에"], "sending": ["동명사", "보내는 것", "send"], "the": ["관사", "그"], "book": ["명사", "책"], "to": ["전치사", "~로, ~에"], "printer": ["명사", "인쇄소"], "publisher": ["명사", "출판사"], "decided": ["동사", "판단했다", "decide"], "it": ["대명사", "그것"], "required": ["동사", "필요로 했다", "require"], "some": ["한정사", "일부의, 어떤"], "editing": ["명사", "편집"]}, "src": "1-"}, {"no": 123, "q": "President Kwon expressed disappointment that GZR Electronics _____ two major clients last year.", "options": ["lose", "loser", "losing", "lost"], "answer": 3, "explain": "정답 (D) lost\n해석: Kwon 회장은 GZR 전자가 작년에 주요 고객 두 곳을 잃은 데 대해 실망을 표했다.\n정답 근거: 명사절 접속사 that 뒤 절의 동사 자리이고 last year라는 과거 시점이 있으므로 과거 동사가 정답이다. 뒤에 목적어가 있어 능동태로 맞다.\n오답 분석: (A) lose: 과거 시점과 시제가 맞지 않는다. / (B) loser: 명사는 동사 자리에 올 수 없다. / (C) losing: 분사는 절의 동사가 될 수 없다.", "translation": "Kwon 회장은 GZR 전자가 작년에 주요 고객 두 곳을 잃은 데 대해 실망을 표했다.", "vocab": "express 동 표현하다 / disappointment 명 실망 / lose – lost 동 잃다", "g": {"president": ["명사", "회장"], "kwon": ["고유명사", "Kwon(인명)"], "expressed": ["동사", "표했다", "express"], "disappointment": ["명사", "실망"], "that": ["접속사", "~라는 것"], "gzr": ["고유명사", "GZR(회사명)"], "electronics": ["고유명사", "Electronics(전자)"], "two": ["숫자", "2"], "major": ["형용사", "주요한"], "clients": ["명사", "고객들", "client"], "last": ["형용사", "지난, 마지막의"], "year": ["명사", "해, 년"]}, "src": "1-"}, {"no": 124, "q": "Alana Beverage Company's popular new tea drink is the _____ of a recent employee brainstorming session.", "options": ["productivity", "productive", "product", "productively"], "answer": 2, "explain": "정답 (C) product\n해석: Alana 음료 회사의 인기 신제품 차 음료는 최근 직원 아이디어 회의의 결과물이다.\n정답 근거: be동사 뒤 보어이자 관사 the의 수식을 받는 명사 자리다. 「결과물」을 뜻하는 product가 문맥에 맞다.\n오답 분석: (A) productivity: '생산성'. 음료가 생산성이라는 뜻이 되어 어색하다. / (B) productive: 형용사는 the 뒤 명사 자리에 올 수 없다. / (D) productively: 부사도 같은 이유로 불가하다.", "translation": "Alana 음료 회사의 인기 신제품 차 음료는 최근 직원 아이디어 회의의 결과물이다.", "vocab": "product 명 산물, 결과물 / brainstorming 명 브레인스토밍 / productivity 명 생산성", "g": {"alana": ["고유명사", "Alana(회사명)"], "beverage": ["명사", "음료"], "company's": ["명사", "회사의", "company"], "popular": ["형용사", "인기 있는"], "new": ["형용사", "새로운"], "tea": ["명사", "차"], "drink": ["명사", "음료"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "of": ["전치사", "~의"], "a": ["관사", "하나의"], "recent": ["형용사", "최근의"], "employee": ["명사", "직원"], "brainstorming": ["명사", "아이디어 회의"], "session": ["명사", "회의, 시간"]}, "src": "1-"}, {"no": 126, "q": "Though Derek Luo's colleagues helped develop the Ortine app, he alone came up with the _____ idea.", "options": ["origin", "originality", "originally", "original"], "answer": 3, "explain": "정답 (D) original\n해석: Derek Luo의 동료들이 Ortine 앱 개발을 도왔지만 최초의 아이디어는 그 혼자 떠올렸다.\n정답 근거: 관사 the와 명사 idea 사이이므로 형용사 자리다.\n오답 분석: (A) origin: 명사가 연달아 와 뜻이 성립하지 않는다. / (B) originality: 명사도 같은 이유로 불가하다. / (C) originally: 부사는 명사를 꾸밀 수 없다.", "translation": "Derek Luo의 동료들이 Ortine 앱 개발을 도왔지만 최초의 아이디어는 그 혼자 떠올렸다.", "vocab": "come up with 구 ~을 생각해 내다 / original 형 최초의, 독창적인 / alone 부 혼자서", "g": {"though": ["접속사", "비록 ~이지만"], "derek": ["고유명사", "Derek(인명)"], "luo's": ["고유명사", "Luo의"], "colleagues": ["명사", "동료들", "colleague"], "helped": ["동사", "도왔다", "help"], "develop": ["동사", "개발하다, 세우다"], "the": ["관사", "그"], "ortine": ["고유명사", "Ortine(앱 이름)"], "app": ["명사", "앱"], "he": ["대명사", "그"], "alone": ["부사", "혼자서"], "came": ["동사", "(came up with) 떠올렸다", "come"], "up": ["부사", "(come up with) 떠올리다"], "with": ["전치사", "~와 함께"], "idea": ["명사", "아이디어"]}, "src": "1-"}, {"no": 128, "q": "The ability to collaborate _____ is one of the most important qualities in a candidate for the social media manager position.", "options": ["effectively", "effect", "effective", "effectiveness"], "answer": 0, "explain": "정답 (A) effectively\n해석: 효과적으로 협업하는 능력은 소셜 미디어 관리자 지원자에게 가장 중요한 자질 중 하나이다.\n정답 근거: collaborate는 자동사여서 뒤에 목적어가 필요 없으므로 빈칸은 동사를 꾸미는 부사 자리다.\n오답 분석: (B) effect: 명사는 자동사 뒤 수식어 자리에 올 수 없다. / (C) effective: 형용사가 꾸밀 명사가 없다. / (D) effectiveness: 명사도 같은 이유로 부적절하다.", "translation": "효과적으로 협업하는 능력은 소셜 미디어 관리자 지원자에게 가장 중요한 자질 중 하나이다.", "vocab": "collaborate 동 협업하다 / effectively 부 효과적으로 / quality 명 자질", "g": {"the": ["관사", "그"], "ability": ["명사", "능력"], "to": ["to부정사", "~하기 위해, ~하는 / ~로"], "collaborate": ["동사", "협업하다"], "is": ["동사", "~이다", "be"], "one": ["숫자", "1, 하나"], "of": ["전치사", "~의"], "most": ["부사", "가장"], "important": ["형용사", "중요한"], "qualities": ["명사", "자질들", "quality"], "in": ["전치사", "~에, ~에서"], "a": ["관사", "하나의"], "candidate": ["명사", "지원자"], "for": ["전치사", "~을 위해, ~에 대해"], "social": ["형용사", "소셜의"], "media": ["명사", "미디어"], "manager": ["명사", "관리자"], "position": ["명사", "직책, 자리"]}, "src": "1-"}, {"no": 101, "q": "Due to technical difficulties, _____ online order cannot be processed at this time.", "options": ["you", "yours", "your", "yourself"], "answer": 2, "explain": "정답 (C) your\n해석: 기술적 문제로 인해 현재 귀하의 온라인 주문을 처리할 수 없습니다.\n정답 근거: 빈칸 뒤에 명사 online order가 있으므로 소유격 자리다.\n오답 분석: (A) you: 주격·목적격은 명사를 꾸밀 수 없다. / (B) yours: 소유대명사 뒤에는 명사가 올 수 없다. / (D) yourself: 재귀대명사는 명사를 수식하지 못한다.", "translation": "기술적 문제로 인해 현재 귀하의 온라인 주문을 처리할 수 없습니다.", "sub": "문법 10회", "vocab": "due to 구 ~ 때문에 / process 동 처리하다 / your 소유격 당신의", "g": {"due": ["형용사", "(due to) ~ 때문에"], "to": ["to부정사", "~하기 위해, ~하는 / ~로"], "technical": ["형용사", "기술적인"], "difficulties": ["명사", "문제, 어려움", "difficulty"], "online": ["형용사", "온라인의"], "order": ["명사", "주문"], "cannot": ["조동사", "~할 수 없다", "can"], "be": ["동사", "~이다, 되다"], "processed": ["과거분사", "처리된", "process"], "at": ["전치사", "~에, ~에서"], "this": ["한정사", "이"], "time": ["명사", "시간, 때"]}, "src": "2-"}, {"no": 103, "q": "The Web site for the Thayerton Chamber of Commerce _____ a comprehensive list of all the businesses 