lerma": ["고유명사", "Guillerma(인명)"], "torres": ["고유명사", "Torres(인명)"], "as": ["전치사", "~로서"], "vice": ["형용사", "부(副)"], "president": ["명사", "사장"], "compliance": ["명사", "(규정) 준수"], "she": ["대명사", "그녀"], "currently": ["부사", "현재"], "chief": ["형용사", "최고의"], "operating": ["형용사", "운영의"], "officer": ["명사", "임원"], "at": ["전치사", "~에서"], "a": ["관사", "하나의"], "leading": ["형용사", "선도적인"], "textile": ["명사", "섬유"], "manufacturer": ["명사", "제조업체"], "wilmington": ["고유명사", "윌밍턴(지명)"], "north": ["형용사", "북쪽의"], "carolina": ["고유명사", "캐롤라이나(지명)"], "2": ["숫자", "2"], "ms": ["명사", "~씨(여성)"], "intends": ["동사", "~할 작정이다", "intend"], "put": ["동사", "(경험을) 활용하다"], "her": ["대명사", "그녀의"], "experience": ["명사", "경험"], "use": ["동사", "이용하다"], "plans": ["명사", "계획", "plan"], "establish": ["동사", "수립하다"], "set": ["과거분사", "정해진", "set"], "best": ["형용사", "가장 좋은", "good"], "practices": ["명사", "관행", "practice"], "year": ["명사", "해, 연도"], "reported": ["동사", "발표했다", "report"], "revenue": ["명사", "매출"], "$10": ["숫자", "$10"], "million": ["숫자", "100만"], "20%": ["숫자", "20%"], "increase": ["명사", "증가"], "profits": ["명사", "이익", "profit"], "3": ["숫자", "3"], "company": ["명사", "회사"], "forecast": ["동사", "예측했다", "forecast"], "similar": ["형용사", "비슷한"], "rise": ["동사", "오르다"], "this": ["한정사", "이"], "4": ["숫자", "4"]}}, {"range": "155-157", "passage": "CELEBRATION OF SERVICE\nCome celebrate longtime employees for their dedicated service to Astoria Industries.\nKeynote address will be given by COO Henry Wilson, who will talk about the changes he has seen in the company over the past 43 years.\nLocal elected officials and all Astoria Industries employees are welcome to attend!\nWednesday, 10 April, 10:00 A.M. to 11:30 A.M.\nA variety of light refreshments will be served.\nAstoria Industries Headquarters, Conference Room B, 29 Hoey Street, Kamo, Whangarei 0112", "tr": "근속 기념 행사\nAstoria Industries에 헌신적으로 봉직한 장기 근속 직원들을 축하하러 오십시오.\n기조연설은 최고 운영 책임자 Henry Wilson이 맡아 지난 43년간 회사에서 목격한 변화를 이야기합니다.\n지역 선출직 공직자와 Astoria Industries 전 직원이 참석하실 수 있습니다!\n4월 10일 수요일 오전 10시 ~ 11시 30분\n다양한 가벼운 다과가 제공됩니다.\nAstoria Industries 본사 B 회의실, Kamo Hoey Street 29번지, 황가레이 0112", "questions": [{"no": 155, "q": "What is the purpose of the April 10 event?", "options": ["To welcome a new company executive", "To celebrate a company anniversary", "To thank a group of employees", "To mark the opening of a new headquarters"], "answer": 2, "explain": "정답 (C) To thank a group of employees\n지문 개요: 회사가 장기 근속 직원을 기리는 행사를 열며 기조연설자와 일시, 장소, 다과 제공을 안내하는 초대장이다.\n정답 근거: 헌신적으로 봉직한 장기 근속 직원들을 축하하는 자리라고 밝힌다.\n오답 분석: (A): 새 임원을 환영하는 행사가 아니다. / (B): 회사 창립 기념 행사가 아니다. / (D): 새 본사 개소를 기념하는 자리가 아니다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "the": ["관사", "그"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "april": ["명사", "4월"], "10": ["숫자", "10"], "event": ["명사", "행사"]}}, {"no": 156, "q": "What is implied about Mr. Wilson?", "options": ["He is an elected official in Whangarei.", "He has worked at Astoria Industries for decades.", "He volunteered to organize the event.", "His office is next to Conference Room B."], "answer": 1, "explain": "정답 (B) He has worked at Astoria Industries for decades.\n정답 근거: 지난 43년간 회사에서 목격한 변화를 이야기한다고 했으므로 수십 년간 근무했음을 알 수 있다.\n오답 분석: (A): 선출직 공직자는 초청 대상으로만 언급된다. / (C): 행사를 준비했다는 언급이 없다. / (D): 사무실 위치에 관한 정보가 없다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "implied": ["과거분사", "암시된", "imply"], "about": ["전치사", "~에 관한"], "mr": ["명사", "~씨(남성)"], "wilson": ["고유명사", "Wilson(인명)"]}}, {"no": 157, "q": "What will most likely be served at the event?", "options": ["A selection of appetizers", "A three-course meal", "A lunch buffet", "A catered brunch"], "answer": 0, "explain": "정답 (A) A selection of appetizers\n정답 근거: 오전 10시부터 11시 30분까지 진행되며 다양한 가벼운 다과가 제공된다고 했으므로 간단한 먹거리가 나온다.\n오답 분석: (B): 정찬 코스 요리는 가벼운 다과와 어울리지 않는다. / (C): 점심 뷔페는 오전에 끝나는 행사와 맞지 않는다. / (D): 케이터링 브런치라는 언급이 없다.", "g": {"what": ["대명사", "무엇"], "will": ["조동사", "~할 것이다"], "most": ["부사", "가장"], "likely": ["부사", "아마"], "be": ["동사", "~이다, 되다"], "served": ["과거분사", "제공되는", "serve"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "event": ["명사", "행사"]}}], "sub": "기출독해 6회", "vocab": "celebration 명 기념 행사 / dedicated 형 헌신적인 / keynote address 명 기조연설 / elected official 명 선출직 공무원 / refreshments 명 다과 || Paraphrase: 155. celebrate longtime employees for their service → thank a group of employees 156. changes over the past 43 years → worked for decades 157. light refreshments → a selection of appetizers", "g": {"celebration": ["명사", "기념 행사"], "of": ["전치사", "~의"], "service": ["명사", "서비스, 근무"], "come": ["동사", "오다"], "celebrate": ["동사", "축하하다"], "longtime": ["형용사", "오랜, 장기 근속의"], "employees": ["명사", "직원들", "employee"], "for": ["전치사", "~을 위해"], "their": ["대명사", "그들의"], "dedicated": ["형용사", "헌신적인"], "to": ["전치사", "~로 / ~하기 위해"], "astoria": ["고유명사", "Astoria(회사명)"], "industries": ["명사", "산업, (회사명) 산업", "industry"], "keynote": ["형용사", "기조(연설)의"], "address": ["명사", "주소"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "given": ["과거분사", "주어지는", "give"], "by": ["전치사", "~에 의해"], "coo": ["명사", "최고 운영 책임자"], "henry": ["고유명사", "Henry(인명)"], "wilson": ["고유명사", "Wilson(인명)"], "who": ["관계사", "~하는 (사람)"], "talk": ["명사", "강연"], "about": ["전치사", "~에 관한"], "the": ["관사", "그"], "changes": ["명사", "변화", "change"], "he": ["대명사", "그"], "has": ["조동사", "(현재완료) ~했다", "have"], "seen": ["과거분사", "본, 목격한", "see"], "in": ["전치사", "~에서, ~에"], "company": ["명사", "회사"], "over": ["전치사", "~ 동안, ~ 넘게"], "past": ["형용사", "지난"], "43": ["숫자", "43"], "years": ["명사", "년, 해", "year"], "local": ["형용사", "지역의"], "elected": ["과거분사", "선출된", "elect"], "officials": ["명사", "공무원들", "official"], "and": ["접속사", "그리고"], "all": ["한정사", "모든"], "are": ["동사", "~이다", "be"], "welcome": ["형용사", "환영받는"], "attend": ["동사", "참석하다"], "wednesday": ["명사", "수요일"], "10": ["숫자", "10"], "april": ["명사", "4월"], "10:00": ["숫자", "10:00"], "a.m": ["부사", "오전"], "11:30": ["숫자", "11:30"], "a": ["관사", "하나의"], "variety": ["명사", "다양함"], "light": ["형용사", "가벼운"], "refreshments": ["명사", "다과"], "served": ["과거분사", "제공되는", "serve"], "headquarters": ["명사", "본사"], "conference": ["명사", "회의, 학회"], "room": ["명사", "회의실, 방"], "b": ["고유명사", "B(회의실 이름)"], "29": ["숫자", "29"], "hoey": ["고유명사", "Hoey(거리명)"], "street": ["명사", "거리"], "kamo": ["고유명사", "Kamo(지명)"], "whangarei": ["고유명사", "황가레이(지명)"], "0112": ["숫자", "0112"]}}, {"range": "158-160", "passage": "Dear Ms. MacGorain,\nThank you for purchasing an Athena Pro Star Platinum membership! Now you can take advantage of our state-of-the-art equipment, as well as our aerobics and indoor cycling classes. Also, you can use your Platinum member card for entry into any Athena Pro Star franchise location. — [1] —.\nWe have processed your initiation fee and prorated monthly fee, which you paid on October 9. — [2] —. From now on, you will be billed on the first of each month. — [3] —. You may make your payment in person or through our Web site. Please allow at least two days for payments made on the Web site to post to your account. — [4] —.\nSincerely, Tamar Chivadze, Membership Services", "tr": "MacGorain 씨께,\nAthena Pro Star 플래티넘 회원권을 구매해 주셔서 감사합니다! 이제 최신 장비는 물론 에어로빅과 실내 사이클 수업도 이용하실 수 있습니다. 또한 플래티넘 회원 카드로 어느 Athena Pro Star 가맹점이든 입장하실 수 있습니다. ―[1]―\n10월 9일에 결제하신 가입비와 일할 계산된 월 회비를 처리했습니다. ―[2]― 이후로는 매달 1일에 청구됩니다. ―[3]― 결제는 직접 방문하시거나 저희 웹사이트를 통해 하실 수 있습니다. 웹사이트로 결제하신 금액이 계정에 반영되기까지 최소 이틀이 걸립니다. ―[4]―\n회원 서비스 Tamar Chivadze 드림", "questions": [{"no": 158, "q": "What type of business is Athena Pro Star?", "options": ["An electronics store", "A fitness club", "A job training service", "A hotel chain"], "answer": 1, "explain": "정답 (B) A fitness club\n지문 개요: 피트니스 클럽이 신규 회원에게 이용 가능한 시설과 지점 이용 혜택, 결제 일정과 방법을 안내하는 편지다.\n정답 근거: 최신 운동 장비와 에어로빅·실내 사이클 수업을 이용할 수 있다고 했으므로 피트니스 클럽이다.\n오답 분석: (A): 전자제품 매장이 아니다. / (C): 직업 훈련 서비스가 아니다. / (D): 호텔 체인이 아니다.", "g": {"what": ["대명사", "무엇"], "type": ["명사", "종류"], "of": ["전치사", "~의"], "business": ["명사", "사업, 업체"], "is": ["동사", "~이다", "be"], "athena": ["고유명사", "Athena(상호)"], "pro": ["고유명사", "Pro(상호 일부)"], "star": ["고유명사", "Star(상호 일부)"]}}, {"no": 159, "q": "According to the letter, on what date will Ms. MacGorain next be billed?", "options": ["October 9", "October 14", "November 1", "November 3"], "answer": 2, "explain": "정답 (C) November 1\n정답 근거: 10월 9일에 가입비와 일할 회비를 냈고 이후로는 매달 1일에 청구된다고 했으므로 다음 청구일은 11월 1일이다.\n오답 분석: (A): 10월 9일은 이미 결제한 날이다. / (B): 10월 14일은 지문에 없는 날짜다. / (D): 11월 3일도 근거가 없다.", "g": {"according": ["전치사", "~에 따라(to와 함께)"], "to": ["전치사", "~에, ~로, ~에게"], "the": ["관사", "그"], "letter": ["명사", "편지"], "on": ["전치사", "~에"], "what": ["대명사", "무엇"], "date": ["명사", "날짜"], "will": ["조동사", "~할 것이다"], "ms": ["명사", "~씨(여성)"], "macgorain": ["고유명사", "MacGorain(인명)"], "next": ["형용사", "다음의"], "be": ["동사", "~이다, 되다"], "billed": ["과거분사", "청구되는", "bill"]}}, {"no": 160, "q": "In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"This includes any of our overseas locations.\"", "options": ["[1]", "[2]", "[3]", "[4]"], "answer": 0, "explain": "정답 (A) [1]\n정답 근거: 제시 문장이 가맹점 이용 범위를 보충하므로 어느 가맹점이든 입장할 수 있다는 문장 바로 뒤가 가장 자연스럽다.\n오답 분석: (B) [2]: 결제 처리 설명 뒤라 지점 이야기가 끼어들어 어색하다. / (C) [3]: 청구 일정 설명 뒤라 흐름이 이어지지 않는다. / (D) [4]: 결제 반영 안내 뒤라 문맥이 끊긴다.", "g": {"in": ["전치사", "~에서, ~에"], "which": ["관계사", "그것은(사물 선행사)"], "of": ["전치사", "~의"], "the": ["관사", "그"], "positions": ["명사", "위치들", "position"], "marked": ["과거분사", "표시된", "mark"], "1": ["숫자", "1"], "2": ["숫자", "2"], "3": ["숫자", "3"], "and": ["접속사", "그리고"], "4": ["숫자", "4"], "does": ["조동사", "(의문문 조동사)", "do"], "following": ["형용사", "다음의"], "sentence": ["명사", "문장"], "best": ["형용사", "가장 좋은", "good"], "belong": ["동사", "속하다, 들어가다"], "this": ["한정사", "이"], "includes": ["동사", "포함하다", "include"], "any": ["한정사", "어떤"], "our": ["대명사", "우리의"], "overseas": ["형용사", "해외의"], "locations": ["명사", "지점들", "location"]}}], "sub": "기출독해 6회", "vocab": "membership 명 회원권 / state-of-the-art 형 최신식의 / franchise 명 가맹점 / initiation fee 명 가입비 / prorated 형 일할 계산된 / bill 동 청구하다 / post 동 반영되다 || Paraphrase: 158. equipment, aerobics and cycling classes → a fitness club 159. billed on the first of each month → November 1 160. entry into any franchise location → includes overseas locations → [1]", "g": {"dear": ["형용사", "~께(편지 인사)"], "ms": ["명사", "~씨(여성)"], "macgorain": ["고유명사", "MacGorain(인명)"], "thank": ["동사", "감사하다"], "you": ["대명사", "당신"], "for": ["전치사", "~을 위해"], "purchasing": ["동명사", "구매하는 것", "purchase"], "an": ["관사", "하나의"], "athena": ["고유명사", "Athena(상호)"], "pro": ["고유명사", "Pro(상호 일부)"], "star": ["고유명사", "Star(상호 일부)"], "platinum": ["고유명사", "Platinum(등급명)"], "membership": ["명사", "회원권"], "now": ["부사", "이제"], "can": ["조동사", "~할 수 있다"], "take": ["동사", "취하다, 들이다"], "advantage": ["명사", "이점(이용하다)"], "of": ["전치사", "~의"], "our": ["대명사", "우리의"], "state-of-the-art": ["형용사", "최신식의"], "equipment": ["명사", "장비"], "as": ["전치사", "~로서"], "well": ["부사", "잘"], "aerobics": ["명사", "에어로빅"], "and": ["접속사", "그리고"], "indoor": ["형용사", "실내의"], "cycling": ["명사", "사이클링"], "classes": ["명사", "수업들", "class"], "also": ["부사", "또한"], "use": ["동사", "이용하다"], "your": ["대명사", "당신의"], "member": ["명사", "회원"], "card": ["명사", "카드"], "entry": ["명사", "입장"], "into": ["전치사", "~ 안으로, ~로"], "any": ["한정사", "어떤"], "franchise": ["명사", "가맹점"], "location": ["명사", "지점"], "1": ["숫자", "1"], "we": ["대명사", "우리"], "have": ["조동사", "(현재완료) ~했다"], "processed": ["과거분사", "처리된", "process"], "initiation": ["명사", "가입"], "fee": ["명사", "요금"], "prorated": ["형용사", "일할 계산된"], "monthly": ["형용사", "매월의"], "which": ["관계사", "그것은(사물 선행사)"], "paid": ["동사", "지불했다", "pay"], "on": ["전치사", "~에"], "october": ["명사", "10월"], "9": ["숫자", "9"], "2": ["숫자", "2"], "from": ["전치사", "~에서, ~로부터"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "billed": ["과거분사", "청구되는", "bill"], "the": ["관사", "그"], "first": ["형용사", "첫 번째의"], "each": ["한정사", "각각의"], "month": ["명사", "달"], "3": ["숫자", "3"], "may": ["조동사", "~해도 된다, ~일 수 있다"], "make": ["동사", "만들다"], "payment": ["명사", "지불, 납부"], "in": ["전치사", "~에서, ~에"], "person": ["명사", "(in person) 직접"], "or": ["접속사", "또는"], "through": ["전치사", "~을 통해"], "web": ["명사", "웹"], "site": ["명사", "사이트"], "please": ["부사", "부디, ~해 주세요"], "allow": ["동사", "(시간을) 감안하다"], "at": ["전치사", "~에서"], "least": ["부사", "(at least) 적어도"], "two": ["숫자", "2"], "days": ["명사", "일, 날", "day"], "payments": ["명사", "납부금", "payment"], "made": ["과거분사", "만들어진, 이루어진", "make"], "to": ["to부정사", "~로 / ~하기 위해"], "post": ["동사", "반영되다"], "account": ["명사", "계좌"], "4": ["숫자", "4"], "sincerely": ["부사", "진심으로(맺음말)"], "tamar": ["고유명사", "Tamar(인명)"], "chivadze": ["고유명사", "Chivadze(인명)"], "services": ["명사", "서비스, 용역", "service"]}}, {"range": "161-163", "passage": "From: Marcia Rollins\nTo: Finance Team; Marketing Team; Interns Team\nDate: September 15\nSubject: Conference Room A\nDear colleagues,\nToday Mr. Cheng from our Beijing office will be visiting us for an urgent meeting with staff members of the Research and Development department. The meeting, which will involve videoconferencing with our international office managers, will be held in Conference Room A. Consequently, the previous plans for Conference Room A have been shifted as follows.\nMs. Sato's group will now meet in Conference Room B. Mr. Garcia has agreed to postpone the meeting with his marketing team. It will now be held tomorrow. Ms. Thompson's meeting with our interns will be held today in the employee cafeteria. The start times originally arranged for these meetings remain unchanged.\nRegards, Marcia Rollins, Administrative Assistant, The Shervington Group", "tr": "발신: Marcia Rollins / 수신: 재무팀, 마케팅팀, 인턴팀 / 날짜: 9월 15일 / 제목: A 회의실\n동료 여러분께,\n오늘 베이징 지사의 Cheng 씨가 연구 개발 부서 직원들과 긴급 회의를 하러 방문합니다. 해외 지사장들과의 화상 회의가 포함된 이 회의는 A 회의실에서 열립니다. 이에 따라 A 회의실에 잡혀 있던 기존 일정이 다음과 같이 조정되었습니다.\nSato 씨 팀은 이제 B 회의실에서 모입니다. Garcia 씨는 마케팅 팀 회의를 미루는 데 동의했습니다. 그 회의는 내일 열립니다. Thompson 씨와 인턴들의 회의는 오늘 직원 식당에서 열립니다. 이 회의들에 원래 정해진 시작 시각은 그대로입니다.\nThe Shervington Group 행정 담당 Marcia Rollins 드림", "questions": [{"no": 161, "q": "What is one purpose of the e-mail?", "options": ["To invite all staff members to meet with a company executive", "To announce a change in equipment in all meeting rooms", "To inform some staff members of meeting locations", "To ask some staff members to attend a technology training meeting"], "answer": 2, "explain": "정답 (C) To inform some staff members of meeting locations\n지문 개요: 행정 담당자가 긴급 회의로 인해 기존에 잡혀 있던 회의들의 장소와 날짜가 어떻게 바뀌는지 부서별로 알리는 이메일이다.\n정답 근거: A 회의실 사용에 따라 각 팀의 회의 장소가 어떻게 바뀌는지 알리고 있다.\n오답 분석: (A): 전 직원을 임원과의 회의에 초대하는 것이 아니다. / (B): 장비 변경 공지가 아니다. / (D): 기술 교육 참석 요청이 아니다.", "g": {"what": ["대명사", "무엇"], "is": ["동사", "~이다", "be"], "one": ["명사", "하나, 한 개"], "purpose": ["명사", "목적"], "of": ["전치사", "~의"], "the": ["관사", "그"], "e-mail": ["명사", "이메일"]}}, {"no": 162, "q": "Whose meeting will be moved to a different day?", "options": ["Mr. Cheng's", "Ms. Sato's", "Mr. Garcia's", "Ms. Thompson's"], "answer": 2, "explain": "정답 (C) Mr. Garcia's\n정답 근거: Garcia 씨가 마케팅 팀 회의를 미루기로 했고 내일 열린다고 했으므로 날짜가 바뀐 회의다.\n오답 분석: (A): Cheng 씨의 회의는 오늘 예정대로 열린다. / (B): Sato 씨 팀은 날짜가 아니라 장소만 바뀜. / (D): Thompson 씨 회의도 오늘 장소만 바뀜.", "g": {"whose": ["대명사", "누구의"], "meeting": ["명사", "회의"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "moved": ["과거분사", "옮겨진", "move"], "to": ["전치사", "~에, ~로, ~에게"], "a": ["관사", "하나의"], "different": ["형용사", "다른"], "day": ["명사", "날"]}}, {"no": 163, "q": "The word \"arranged\" in paragraph 2, line 4, is closest in meaning to", "options": ["straightened", "established", "adapted", "classified"], "answer": 1, "explain": "정답 (B) established\n정답 근거: 원래 「정해진」 시작 시각이라는 뜻이므로 정해 두었다는 의미의 established가 가장 가깝다.\n오답 분석: (A) straightened: '똑바르게 하다'. 일정과 무관하다. / (C) adapted: '조정된'. 시각이 그대로라는 내용과 어긋남. / (D) classified: '분류된'. 뜻이 다르다.", "g": {"the": ["관사", "그"], "word": ["명사", "단어"], "arranged": ["과거분사", "정해진", "arrange"], "in": ["전치사", "~에서, ~에"], "paragraph": ["명사", "단락"], "2": ["숫자", "2"], "line": ["명사", "제품군, 줄"], "4": ["숫자", "4"], "is": ["동사", "~이다", "be"], "closest": ["형용사", "가장 가까운", "close"], "meaning": ["명사", "의미"], "to": ["전치사", "~에, ~로, ~에게"]}}], "sub": "기출독해 6회", "vocab": "urgent 형 긴급한 / videoconferencing 명 화상회의 / consequently 부 따라서 / shift 동 옮기다 / postpone 동 연기하다 / arrange 동 정하다, 마련하다 || Paraphrase: 161. previous plans have been shifted → inform staff of meeting locations 162. Mr. Garcia postpone held tomorrow → Mr. Garcia's 163. originally arranged → established", "g": {"from": ["전치사", "~에서, ~로부터"], "marcia": ["고유명사", "Marcia(인명)"], "rollins": ["고유명사", "Rollins(인명)"], "to": ["to부정사", "~하기 위해, ~하는"], "finance": ["동사", "자금을 대다"], "team": ["명사", "팀"], "marketing": ["명사", "마케팅"], "interns": ["명사", "인턴들", "intern"], "date": ["명사", "날짜"], "september": ["명사", "9월"], "15": ["숫자", "15"], "subject": ["형용사", "~의 대상인"], "conference": ["명사", "회의, 학회"], "room": ["명사", "회의실, 방"], "a": ["관사", "하나의"], "dear": ["형용사", "~께(편지 인사)"], "colleagues": ["명사", "동료들", "colleague"], "today": ["부사", "오늘"], "mr": ["명사", "~씨(남성)"], "cheng": ["고유명사", "Cheng(인명)"], "our": ["대명사", "우리의"], "beijing": ["고유명사", "베이징(지명)"], "office": ["명사", "사무실"], "will": ["조동사", "~할 것이다"], "be": ["동사", "~이다, 되다"], "visiting": ["현재분사", "방문하는", "visit"], "us": ["대명사", "우리를, 우리에게"], "for": ["전치사", "~을 위해"], "an": ["관사", "하나의"], "urgent": ["형용사", "긴급한"], "meeting": ["명사", "회의"], "with": ["전치사", "~와 함께, ~으로"], "staff": ["명사", "직원"], "members": ["명사", "구성원들", "member"], "of": ["전치사", "~의"], "the": ["관사", "그"], "research": ["명사", "연구"], "and": ["접속사", "그리고"], "development": ["명사", "개발"], "department": ["명사", "부서"], "which": ["관계사", "그것은(사물 선행사)"], "involve": ["동사", "포함하다"], "videoconferencing": ["명사", "화상 회의"], "international": ["형용사", "국제의, 해외의"], "managers": ["명사", "관리자들", "manager"], "held": ["과거분사", "열리는", "hold"], "in": ["전치사", "~에서, ~에"], "consequently": ["부사", "그 결과, 따라서"], "previous": ["형용사", "이전의"], "plans": ["명사", "계획", "plan"], "have": ["조동사", "(현재완료) ~했다"], "been": ["과거분사", "~였다(과거분사)", "be"], "shifted": ["과거분사", "변경된", "shift"], "as": ["전치사", "~로서"], "follows": ["동사", "다음과 같다", "follow"], "ms": ["명사", "~씨(여성)"], "sato's": ["고유명사", "Sato의"], "group": ["명사", "그룹, 단체"], "now": ["부사", "이제"], "meet": ["동사", "만나다"], "b": ["고유명사", "B(회의실 이름)"], "garcia": ["고유명사", "Garcia(인명)"], "has": ["조동사", "(현재완료) ~했다", "have"], "agreed": ["동사", "동의했다", "agree"], "postpone": ["동사", "연기하다"], "his": ["대명사", "그의"], "it": ["대명사", "그것"], "tomorrow": ["부사", "내일"], "thompson's": ["고유명사", "Thompson의"], "employee": ["명사", "직원"], "cafeteria": ["명사", "구내식당"], "start": ["명사", "시작"], "times": ["명사", "시각", "time"], "originally": ["부사", "원래"], "arranged": ["과거분사", "정해진", "arrange"], "these": ["한정사", "이러한"], "meetings": ["명사", "회의들", "meeting"], "remain": ["동사", "여전히 ~이다"], "unchanged": ["형용사", "변경되지 않은"], "regards": ["명사", "안부(맺음말)", "regard"], "administrative": ["형용사", "행정의"], "assistant": ["명사", "보조, 비서"], "shervington": ["고유명사", "회사명"]}}]}$mkd$::jsonb,now()) on conflict (key) do update set data=excluded.data, updated_at=now();
insert into content(key,data,updated_at) values('sec:a2-r9-p5',$mkd${"id": "a2-r9-p5", "area": "RC", "part": 5, "group": "A급 과제", "series": 2, "round": 9, "level": "중급", "title": "A급 과제 9회 · PART 5 (어휘 3·4회)", "notes": [], "items": [{"no": 102, "q": "The university's new garden, designed _____ Dr. Elsa Sayles, is now open.", "options": ["by", "out", "down", "across"], "answer": 0, "explain": "정답 (A) by\n해석: Elsa Sayles 박사가 설계한 대학교의 새 정원이 이제 개방되었다.\n정답 근거: 과거분사 designed 뒤에서 행위자를 나타내야 하므로 「~에 의해」를 뜻하는 by가 알맞다.\n오답 분석: (B) out: 방향을 나타내 행위자를 표시하지 못한다. / (C) down: 위치·방향을 뜻해 문맥과 맞지 않는다. / (D) across: '~을 가로질러'. 설계자를 나타내지 못한다.", "translation": "Elsa Sayles 박사가 설계한 대학교의 새 정원이 이제 개방되었다.", "vocab": "design 동 설계하다 / by 전 ~에 의해 / open 형 개방된", "g": {"the": ["관사", "그"], "university's": ["명사", "대학교의", "university"], "new": ["형용사", "새로운"], "garden": ["명사", "정원"], "designed": ["과거분사", "설계된", "design"], "dr": ["명사", "박사"], "elsa": ["고유명사", "Elsa(인명)"], "sayles": ["고유명사", "Sayles(인명)"], "is": ["동사", "~이다", "be"], "now": ["부사", "이제"], "open": ["동사", "문을 열다"]}, "src": "1-"}, {"no": 105, "q": "Inspectors _____ examine each box of Julie's Baked Delights before shipment.", "options": ["exactly", "far", "carefully", "quite"], "answer": 2, "explain": "정답 (C) carefully\n해석: 검사원들은 출하 전에 각 상자를 꼼꼼히 검사한다.\n정답 근거: 검사 행위의 방식을 나타내야 하므로 「꼼꼼히」를 뜻하는 carefully가 알맞다.\n오답 분석: (A) exactly: '정확히'. 수치를 특정할 때 주로 쓰인다. / (B) far: 정도·거리를 나타내 동사를 꾸미기에 어색하다. / (D) quite: 형용사·부사를 강조하며 단독으로 동사를 꾸미지 않는다.", "translation": "검사원들은 출하 전에 각 상자를 꼼꼼히 검사한다.", "vocab": "inspector 명 검사관 / carefully 부 신중히 / examine 동 검사하다 / shipment 명 배송", "g": {"inspectors": ["명사", "검사관들", "inspector"], "examine": ["동사", "검사하다"], "each": ["한정사", "각각의"], "box": ["명사", "상자"], "of": ["전치사", "~의"], "julie's": ["고유명사", "Julie's(상호)"], "baked": ["과거분사", "구운", "bake"], "delights": ["고유명사", "Delights(상호 일부)"], "before": ["전치사", "~ 전에"], "shipment": ["명사", "발송"]}, "src": "1-"}, {"no": 106, "q": "Norwind ceiling fans are praised for having a unique _____ and excellent durability.", "options": ["design", "tradition", "prediction", "leadership"], "answer": 0, "explain": "정답 (A) design\n해석: Norwind 천장 선풍기는 독특한 디자인과 뛰어난 내구성으로 호평받는다.\n정답 근거: 제품이 칭찬받는 요소이고 형용사 unique의 수식을 받으므로 「디자인」이 알맞다.\n오답 분석: (B) tradition: '전통'. 제품의 특징으로 어색하다. / (C) prediction: '예측'. 칭찬 대상이 되지 못한다. / (D) leadership: '지도력'. 제품과 무관하다.", "translation": "Norwind 천장 선풍기는 독특한 디자인과 뛰어난 내구성으로 호평받는다.", "vocab": "ceiling fan 명 천장 선풍기 / praise 동 칭찬하다 / design 명 디자인 / durability 명 내구성", "g": {"norwind": ["고유명사", "Norwind(브랜드명)"], "ceiling": ["명사", "천장"], "fans": ["명사", "선풍기들", "fan"], "are": ["동사", "~이다", "be"], "praised": ["과거분사", "칭찬받는", "praise"], "for": ["전치사", "~을 위해"], "having": ["동명사", "가지고 있는 것", "have"], "a": ["관사", "하나의"], "unique": ["형용사", "독특한"], "and": ["접속사", "그리고"], "excellent": ["형용사", "훌륭한"], "durability": ["명사", "내구성"]}, "src": "1-"}, {"no": 109, "q": "To avoid processing delays, please _____ both your billing and mailing addresses.", "options": ["buy", "admit", "enter", "join"], "answer": 2, "explain": "정답 (C) enter\n해석: 처리 지연을 피하려면 청구지 주소와 배송지 주소를 모두 입력해 주십시오.\n정답 근거: 주소를 목적어로 취해 「입력하다」를 뜻해야 하므로 enter가 알맞다.\n오답 분석: (A) buy: '사다'. 주소를 목적어로 취할 수 없다. / (B) admit: '인정하다'. 문맥과 맞지 않는다. / (D) join: '결합하다'. 주소 기입을 뜻하지 않는다.", "translation": "처리 지연을 피하려면 청구지 주소와 배송지 주소를 모두 입력해 주십시오.", "vocab": "avoid 동 피하다 / processing 명 처리 / enter 동 입력하다 / billing address 명 청구지 주소", "g": {"to": ["to부정사", "~하기 위해, ~하는"], "avoid": ["동사", "피하다"], "processing": ["명사", "처리"], "delays": ["명사", "지연", "delay"], "please": ["부사", "부디, ~해 주세요"], "both": ["한정사", "둘 다"], "your": ["대명사", "당신의"], "billing": ["명사", "청구(서)"], "and": ["접속사", "그리고"], "mailing": ["명사", "우편 발송"], "addresses": ["명사", "주소들", "address"]}, "src": "1-"}, {"no": 110, "q": "Hard hats must be worn throughout the factory, _____ while eating in the cafeteria.", "options": ["so", "if", "except", "some"], "answer": 2, "explain": "정답 (C) except\n해석: 구내식당에서 식사할 때를 제외하고 공장 전역에서 안전모를 착용해야 한다.\n정답 근거: 전체 규칙에서 한 가지 상황만 빠진다는 뜻이므로 「~을 제외하고」가 알맞다.\n오답 분석: (A) so: 결과를 나타내 예외를 표현하지 못한다. / (B) if: 조건을 나타내며 뒤 구조와 어울리지 않는다. / (D) some: 형용사·대명사라 이 자리에 맞지 않는다.", "translation": "구내식당에서 식사할 때를 제외하고 공장 전역에서 안전모를 착용해야 한다.", "vocab": "hard hat 명 안전모 / throughout 전 ~전역에서 / except 전 ~을 제외하고", "g": {"hard": ["형용사", "단단한"], "hats": ["명사", "모자", "hat"], "must": ["조동사", "~해야 한다"], "be": ["동사", "~이다, 되다"], "worn": ["과거분사", "착용된", "wear"], "throughout": ["전치사", "~ 전역에, 내내"], "the": ["관사", "그"], "factory": ["명사", "공장"], "while": ["접속사", "~하는 동안"], "eating": ["동명사", "먹는 것", "eat"], "in": ["전치사", "~에서, ~에"], "cafeteria": ["명사", "구내식당"]}, "src": "1-"}, {"no": 111, "q": "Each employee will receive a bonus at the end of the year _____ Robinson Manufacturing's exceptional profits.", "options": ["thanks to", "in addition to", "as far as", "even so"], "answer": 0, "explain": "정답 (A) thanks to\n해석: Robinson Manufacturing의 뛰어난 수익 덕분에 각 직원은 연말에 상여금을 받는다.\n정답 근거: 상여금 지급의 긍정적인 원인을 나타내야 하므로 「~덕분에」가 알맞다.\n오답 분석: (B) in addition to: 추가를 뜻해 인과 관계를 나타내지 못한다. / (C) as far as: 범위를 나타내 문맥과 맞지 않는다. / (D) even so: 접속부사라 뒤에 명사를 이끌지 못한다.", "translation": "Robinson Manufacturing의 뛰어난 수익 덕분에 각 직원은 연말에 상여금을 받는다.", "vocab": "thanks to 구 ~덕분에 / exceptional 형 이례적인, 뛰어난 / profit 명 이익", "g": {"each": ["한정사", "각각의"], "employee": ["명사", "직원"], "will": ["조동사", "~할 것이다"], "receive": ["동사", "받다"], "a": ["관사", "하나의"], "bonus": ["명사", "보너스"], "at": ["전치사", "~에서"], "the": ["관사", "그"], "end": ["명사", "끝"], "of": ["전치사", "~의"], "year": ["명사", "해, 연도"], "robinson": ["고유명사", "Robinson(회사명)"], "manufacturing's": ["고유명사", "Manufacturing의"], "exceptional": ["형용사", "이례적인, 뛰어난"], "profits": ["명사", "이익", "profit"]}, "src": "1-"}, {"no": 113, "q": "Lydex Industrial Supply's _____ manufacturing process has become a model for other companies looking to save money.", "options": ["priced", "average", "skillful", "economical"], "answer": 3, "explain": "정답 (D) economical\n해석: Lydex Industrial Supply의 경제적인 제조 공정은 비용을 절감하려는 다른 회사들의 본보기가 되었다.\n정답 근거: 비용을 절감하려는 회사들의 본보기가 되었다고 했으므로 「경제적인」이 알맞다.\n오답 분석: (A) priced: '가격이 매겨진'. 공정을 꾸미기에 어색하다. / (B) average: '평균의'. 본보기가 되는 이유로 부적절하다. / (C) skillful: '숙련된'. 비용 절감과 직접 연결되지 않는다.", "translation": "Lydex Industrial Supply의 경제적인 제조 공정은 비용을 절감하려는 다른 회사들의 본보기가 되었다.", "vocab": "economical 형 경제적인 / manufacturing 명 제조 / process 명 공정 / save 동 절약하다", "g": {"lydex": ["고유명사", "Lydex(회사명)"], "industrial": ["형용사", "산업의"], "supply's": ["고유명사", "Supply의"], "manufacturing": ["명사", "제조"], "process": ["동사", "처리하다"], "has": ["조동사", "(현재완료) ~했다", "have"], "become": ["과거분사", "되다(과거분사)", "become"], "a": ["관사", "하나의"], "model": ["명사", "본보기"], "for": ["전치사", "~을 위해"], "other": ["형용사", "다른"], "companies": ["명사", "회사들", "company"], "looking": ["현재분사", "찾고 있는", "look"], "to": ["to부정사", "~하기 위해, ~하는"], "save": ["동사", "아끼다, 절약하다"], "money": ["명사", "돈"]}, "src": "1-"}, {"no": 114, "q": "Employees _____ hired at Jontsan Shipping receive one month of training.", "options": ["reportedly", "secondly", "frequently", "newly"], "answer": 3, "explain": "정답 (D) newly\n해석: Jontsan Shipping에 새로 채용된 직원들은 한 달간 교육을 받는다.\n정답 근거: 과거분사 hired를 꾸며 채용 시점을 나타내야 하므로 「새로」를 뜻하는 newly가 알맞다.\n오답 분석: (A) reportedly: '전하는 바에 따르면'. 교육 대상을 특정하지 못한다. / (B) secondly: '두 번째로'. 문맥과 맞지 않는다. / (C) frequently: '자주'. 채용 시점을 나타내지 못한다.", "translation": "Jontsan Shipping에 새로 채용된 직원들은 한 달간 교육을 받는다.", "vocab": "newly 부 새로 / hire 동 고용하다 / training 명 교육", "g": {"employees": ["명사", "직원들", "employee"], "hired": ["동사", "채용했다", "hire"], "at": ["전치사", "~에서"], "jontsan": ["고유명사", "Jontsan(회사명)"], "shipping": ["동명사", "발송하는 것", "ship"], "receive": ["동사", "받다"], "one": ["명사", "하나, 한 개"], "month": ["명사", "달"], "of": ["전치사", "~의"], "training": ["명사", "교육"]}, "src": "1-"}, {"no": 115, "q": "You must consult Ms. Saito before making any _____ to the rental agreement.", "options": ["turns", "revisions", "shapes", "choices"], "answer": 1, "explain": "정답 (B) revisions\n해석: 임대 계약서를 수정하기 전에 Saito 씨와 상의해야 한다.\n정답 근거: 계약서에 가하는 변경을 뜻해야 하므로 「수정」이 알맞고 뒤의 to와 자연스럽게 이어진다.\n오답 분석: (A) turns: '차례·회전'. 계약서 변경을 뜻하지 않는다. / (C) shapes: '모양'. 문맥과 무관하다. / (D) choices: '선택'. 계약서에 가하는 변경을 나타내지 못한다.", "translation": "임대 계약서를 수정하기 전에 Saito 씨와 상의해야 한다.", "vocab": "consult 동 상의하다 / revision 명 수정 / rental agreement 명 임대 계약", "g": {"you": ["대명사", "당신"], "must": ["조동사", "~해야 한다"], "consult": ["동사", "상의하다"], "ms": ["명사", "~씨(여성)"], "saito": ["고유명사", "Saito(인명)"], "before": ["전치사", "~ 전에"], "making": ["동명사", "하는 것", "make"], "any": ["한정사", "어떤"], "to": ["전치사", "~에, ~로, ~에게"], "the": ["관사", "그"], "rental": ["명사", "대여, 임대"], "agreement": ["명사", "계약(서)"]}, "src": "1-"}, {"no": 116, "q": "With a variety of clever features, the OF4 runner's watch is definitely _____ its price.", "options": ["within", "worth", "high", "on"], "answer": 1, "explain": "정답 (B) worth\n해석: 다양한 기발한 기능을 갖춘 OF4 러닝 시계는 분명히 값어치를 한다.\n정답 근거: be worth + 명사는 「~의 값어치가 있다」를 뜻하므로 가격에 값한다는 문맥에 맞다.\n오답 분석: (A) within: '~이내에'. 가치를 나타내지 못한다. / (C) high: 뒤에 명사를 바로 취하지 못한다. / (D) on: 가치를 표현하는 쓰임이 아니다.", "translation": "다양한 기발한 기능을 갖춘 OF4 러닝 시계는 분명히 값어치를 한다.", "vocab": "a variety of 구 다양한 / feature 명 기능 / worth 전 ~의 가치가 있는 / definitely 부 확실히", "g": {"with": ["전치사", "~와 함께, ~으로"], "a": ["관사", "하나의"], "variety": ["명사", "다양함"], "of": ["전치사", "~의"], "clever": ["형용사", "기발한"], "features": ["명사", "기능들", "feature"], "the": ["관사", "그"], "of4": ["고유명사", "OF4(제품명)"], "runner's": ["명사", "달리기용의", "runner"], "watch": ["명사", "손목시계"], "is": ["동사", "~이다", "be"], "definitely": ["부사", "확실히"], "its": ["대명사", "그것의"], "price": ["명사", "가격"]}, "src": "1-"}, {"no": 117, "q": "At press conferences, the mayor often _____ to reporters' questions with optimism and humor.", "options": ["remains", "responds", "applies", "announces"], "answer": 1, "explain": "정답 (B) responds\n해석: 기자회견에서 시장은 종종 기자들의 질문에 낙관과 유머로 답한다.\n정답 근거: 뒤에 전치사 to가 이어지며 질문에 답한다는 뜻이므로 respond to 형태를 이루는 responds가 알맞다.\n오답 분석: (A) remains: '남다'. 질문에 대한 반응을 나타내지 못한다. / (C) applies: apply to는 '적용되다'라는 뜻이라 문맥과 다르다. / (D) announces: 타동사라 뒤에 to가 오지 않는다.", "translation": "기자회견에서 시장